function getActiveReligions(year) {
  return RELIGIONS.map(function(rel){
    var period=null;
    for(var i=rel.periods.length-1;i>=0;i--){
      if(year>=rel.periods[i].start){period=rel.periods[i];break;}
    }
    if(!period||year>period.end+200)return null;
    return { id:rel.id, name:rel.name, color:rel.color, rings:period.rings, wikiTitle:rel.wikiTitle };
  }).filter(Boolean);
}

