const TOLERANCE_STEPS = [0, 1, 2, 5, 10, 25, 50, 100, 250, 500];

// ─── Helpers ──────────────────────────────────────────────────────────────────
function getNarrative(year) {
  return NARRATIVES.find(n => year >= n.start && year <= n.end)?.text || '';
}
// Los periodos son semiabiertos [start, end): el año en que una civilización
// cede el paso a otra pertenece solo a la que empieza. Con el límite inclusivo
// que había antes, en cada año de relevo (206 a.C. con Qin y Han, por ejemplo)
// se pintaban las dos a la vez y aparecían dos etiquetas encima del mismo
// territorio. El último año de los datos sí es inclusivo, para que 2025 pinte.
const ULTIMO_ANIO = 2025;
const ANIO_MIN = -70000;   // mismo tope que la rueda de años
function periodoEn(periods, year) {
  for (var i = periods.length - 1; i >= 0; i--) {
    var p = periods[i];
    if (year < p.start) continue;
    if (year < p.end || (p.end >= ULTIMO_ANIO && year <= p.end)) return p;
  }
  return undefined;
}
function getActiveCivils(year) {
  return CIVILIZATIONS.map(civ => {
    const period = periodoEn(civ.periods, year);
    if (!period) return null;
    // Sin fundido: aparece/desaparece de golpe en los límites del periodo.
    // name: si el periodo define un nombre propio (ej. Austria antes de 1867
    // no debería llamarse "Imperio Austrohúngaro" -- ver periodName más
    // abajo), pisa el nombre genérico del civ tanto en el chip de la leyenda
    // como en el título de la ficha.
    // inc: el periodo tiene contorno de relleno y no de frontera conocida. Viaja
    // al motor para que lo dibuje apagado y a trazos.
    return { ...civ, name: period.name || civ.name, baseName: civ.name, periodName: period.name, rings: period.rings, periodStart: period.start, periodEnd: period.end, periodWikiTitle: period.wikiTitle, inc: period.inc, opacity: 1 };
  }).filter(Boolean);
}
function getActiveRoutes(year) {
  return TRADE_ROUTES.filter(r => r.periods.some(p => year >= p.start && year <= p.end));
}
function getActiveWars(year) {
  return WARS.filter(w => year >= w.yearStart && year <= w.yearEnd);
}

