// ── Layer altitude scheme ───────────────────────────────────────────────────
// Each process layer renders its area/path at its OWN radius above the globe
// surface (1.0), spaced 0.004 apart, so two layers active at once never sit
// on the exact same shell -- previously civilizations and languages were
// BOTH at 1.016 (literally identical) and religion at 1.017 (0.001 away),
// which caused z-fighting/flicker and made it impossible to tell which
// translucent blob belonged to which layer when several were toggled on
// together. Order (innermost -> outermost) follows "static territory" to
// "dynamic overlay": civilizations 1.014, religion 1.018, languages 1.022,
// wars 1.026, routes 1.030, migration 1.034.
// ── Capa de territorios fusionada ───────────────────────────────────────────
// Cada territorio (civilizacion + periodo, la clave 'k') se triangula UNA vez
// y se guarda como buffers sueltos. Al pintar, los buffers de los territorios
// activos se concatenan en una sola malla de relleno y una sola geometria de
// perimetro: cuatro llamadas de dibujo en total en vez de miles.
var civCache=Object.create(null);       // clave -> {fp,fc,lp,lc,etiqueta,civId,uso}
var civModo='';                         // firma del modo de dibujo: 2D/3D + nombres
var civUso=0;
var CIV_CACHE_MAX=700;
var civFillMesh=null,civLineas=[],civTriIds=[],civPuntos=null;
var civEtiquetas=Object.create(null);   // clave -> sprite en escena

function avisarRN(m){
  if(window.ReactNativeWebView)window.ReactNativeWebView.postMessage(JSON.stringify(m));
}
function ponerAtributo(geo,nombre,arr,tam){
  var at=geo.getAttribute(nombre);
  if(at&&at.array.length===arr.length){at.copyArray(arr);at.needsUpdate=true;}
  else geo.setAttribute(nombre,new THREE.BufferAttribute(arr,tam));
  geo.setDrawRange(0,arr.length/tam);
  if(nombre==='position')geo.computeBoundingSphere();
}
// ── El velo de la tierra sin entidad ──────────────────────────────────────
// Anillos de base_tierra.js (tierra firme menos vacios permanentes), pintados
// una vez por proyeccion a un radio por debajo de las civilizaciones. Normal
// blending y poca opacidad: un velo, no una capa.
var baseTierraRings=[],baseTierraMesh=null;
function construirBaseTierra(){
  if(baseTierraMesh){procesGroup.remove(baseTierraMesh);baseTierraMesh.geometry.dispose();baseTierraMesh.material.dispose();baseTierraMesh=null;}
  if(!baseTierraRings.length)return;
  var verts=[];
  for(var i=0;i<baseTierraRings.length;i++){
    var fv=fillVertsFromRing(densifyRing(baseTierraRings[i],4),1.011);
    for(var a=0;a<fv.length;a++)verts.push(fv[a]);
  }
  var geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(verts),3));
  geo.computeBoundingSphere();
  baseTierraMesh=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:0xcbbd9e,transparent:true,opacity:0.20,side:THREE.DoubleSide,depthWrite:false}));
  baseTierraMesh.renderOrder=1;
  baseTierraMesh.visible=!!state.civilizations&&state.baseOn!==false;
  procesGroup.add(baseTierraMesh);
}
// Las aristas de las areas culturales van en su propia geometria, con un solo
// halo tenue y sin la linea blanca: el contorno de un sustrato no es una
// frontera medida.
var civLineasCult=null;
function crearMallasCivs(){
  var gF=new THREE.BufferGeometry();
  civFillMesh=new THREE.Mesh(gF,new THREE.MeshBasicMaterial({
    vertexColors:true,transparent:true,opacity:0.60,side:THREE.DoubleSide,
    depthWrite:false,blending:THREE.AdditiveBlending}));
  civFillMesh.renderOrder=2;civFillMesh.userData={capaCivs:true};
  procesGroup.add(civFillMesh);
  // Una sola geometria de perimetro compartida por las tres pasadas de trazo
  // (halo ancho tenue, halo medio y linea nitida): el grosor de linea no es
  // fiable en WebGL, asi que se sigue simulando apilando trazos a distintos
  // radios, pero ahora cuesta tres llamadas en total y no tres por anillo.
  var gL=new THREE.BufferGeometry();
  var capas=[
    {escala:1.022,mat:new THREE.LineBasicMaterial({vertexColors:true,opacity:0.45,transparent:true,blending:THREE.AdditiveBlending})},
    {escala:1.014,mat:new THREE.LineBasicMaterial({vertexColors:true,opacity:0.90,transparent:true,blending:THREE.AdditiveBlending})},
    {escala:1.0145,mat:new THREE.LineBasicMaterial({color:0xffffff,opacity:0.55,transparent:true})},
  ];
  var gC=new THREE.BufferGeometry();
  civLineasCult=new THREE.LineSegments(gC,new THREE.LineBasicMaterial({vertexColors:true,opacity:0.30,transparent:true,blending:THREE.AdditiveBlending}));
  civLineasCult.scale.setScalar(1.014);civLineasCult.renderOrder=3;procesGroup.add(civLineasCult);
  civLineas=capas.map(function(c){
    var ls=new THREE.LineSegments(gL,c.mat);
    ls.scale.setScalar(c.escala);ls.renderOrder=3;procesGroup.add(ls);return ls;
  });
  // Puntos de presencia para las islas que no llegan a un pixel. La opcion
  // sizeAttenuation en false hace que el tamano sea en PIXELES y no en unidades
  // del mundo: el punto no crece al acercarse, asi que el poligono real acaba
  // desbordandolo y tomando el relevo. depthTest en true para que los del otro
  // lado del globo queden ocultos por la Tierra.
  var gP=new THREE.BufferGeometry();
  civPuntos=new THREE.Points(gP,new THREE.PointsMaterial({
    vertexColors:true,size:5,sizeAttenuation:false,
    transparent:true,opacity:0.95,depthTest:true,depthWrite:false}));
  civPuntos.renderOrder=4;civPuntos.userData={capaCivs:true};
  procesGroup.add(civPuntos);
}
function soltarEntrada(e){
  if(e&&e.etiqueta){
    if(e.etiqueta.material){
      if(e.etiqueta.material.map)e.etiqueta.material.map.dispose();
      e.etiqueta.material.dispose();
    }
  }
}
function ocultarCapaCivs(){
  if(civFillMesh)civFillMesh.visible=false;
  if(civLineasCult)civLineasCult.visible=false;
  for(var i=0;i<civLineas.length;i++)civLineas[i].visible=false;
  for(var k in civEtiquetas){procesGroup.remove(civEtiquetas[k]);delete civEtiquetas[k];}
  layerMeshes.civils=[];
}
// El cambio de globo a mapa plano, o encender/apagar los nombres, invalida
// toda la geometria cacheada: hay que rehacerla con las nuevas proyecciones.
function purgarCivCache(){
  ocultarCapaCivs();
  for(var k in civCache)soltarEntrada(civCache[k]);
  civCache=Object.create(null);
  civTriIds=[];
}

function rebuildCivils(civils){
  var modo=(MAP2D?'2d':'3d')+(state.showCivilNames?'|n':'');
  if(modo!==civModo){purgarCivCache();civModo=modo;}
  if(!state.civilizations||!civils){ocultarCapaCivs();return;}

  var vivos=Object.create(null),orden=[],faltantes=false;
  for(var ci=0;ci<civils.length;ci++){
    var cv=civils[ci];
    var clave=cv.k||cv.id;
    var ent=civCache[clave];
    if(!ent){
      var geo=cv.rings||(cv.ring?[cv.ring]:null);
      if(!geo||!geo.length){faltantes=true;continue;}
      ent=civCache[clave]=construirCivil(cv,geo);
      ent.clave=clave;ent.uso=0;
    }
    ent.uso=++civUso;vivos[clave]=1;orden.push(ent);
  }

  // ── Fusion de toda la capa en unas pocas mallas ───────────────────────────
  // Antes cada anillo generaba cuatro objetos (relleno + dos halos + linea):
  // en 1800 eran 6.754 objetos, o sea 6.754 llamadas de dibujo por fotograma,
  // muy por encima de lo que aguanta una GPU de movil. Por eso se atascaba
  // hasta al rotar el globo, no solo al reproducir. Ahora todo el relleno va
  // en UNA malla y todo el perimetro en UNA geometria compartida por las tres
  // pasadas de trazo: cuatro llamadas en total, sea cual sea el año.
  var nF=0,nL=0,nP=0;
  var nQ=0;
  for(var o=0;o<orden.length;o++){nF+=orden[o].fp.length;nL+=orden[o].lp.length;nP+=(orden[o].pp?orden[o].pp.length:0);nQ+=(orden[o].lq?orden[o].lq.length:0);}
  var QP=new Float32Array(nQ),QC=new Float32Array(nQ),offQ=0;
  var FP=new Float32Array(nF),FC=new Float32Array(nF),LP=new Float32Array(nL),LC=new Float32Array(nL);
  var PP=new Float32Array(nP),PC=new Float32Array(nP);
  var offF=0,offL=0,offP=0;
  civTriIds=new Array(nF/9);
  var tri=0;
  for(var o2=0;o2<orden.length;o2++){
    var e2=orden[o2];
    FP.set(e2.fp,offF);FC.set(e2.fc,offF);offF+=e2.fp.length;
    LP.set(e2.lp,offL);LC.set(e2.lc,offL);offL+=e2.lp.length;
    if(e2.lq&&e2.lq.length){QP.set(e2.lq,offQ);QC.set(e2.lqc,offQ);offQ+=e2.lq.length;}
    if(e2.pp&&e2.pp.length){PP.set(e2.pp,offP);PC.set(e2.pc,offP);offP+=e2.pp.length;}
    for(var t2=e2.fp.length/9;t2>0;t2--)civTriIds[tri++]=e2.civId;
  }

  if(!civFillMesh)crearMallasCivs();
  ponerAtributo(civFillMesh.geometry,'position',FP,3);
  ponerAtributo(civFillMesh.geometry,'color',FC,3);
  for(var g=0;g<civLineas.length;g++){
    ponerAtributo(civLineas[g].geometry,'position',LP,3);
    ponerAtributo(civLineas[g].geometry,'color',LC,3);
  }

  // Etiquetas: siguen siendo sprites sueltos (uno por territorio, no por
  // anillo), pero se reutilizan y solo entran o salen de la escena cuando
  // cambia el conjunto activo.
  for(var k in civEtiquetas){
    if(!vivos[k]){procesGroup.remove(civEtiquetas[k]);delete civEtiquetas[k];}
  }
  for(var o3=0;o3<orden.length;o3++){
    var e3=orden[o3];
    if(!e3.etiqueta||civEtiquetas[e3.clave])continue;
    procesGroup.add(e3.etiqueta);civEtiquetas[e3.clave]=e3.etiqueta;
  }
  if(civPuntos){
    ponerAtributo(civPuntos.geometry,'position',PP,3);
    ponerAtributo(civPuntos.geometry,'color',PC,3);
    civPuntos.visible=nP>0;
  }
  civFillMesh.visible=nF>0;
  for(var g3=0;g3<civLineas.length;g3++)civLineas[g3].visible=nL>0;
  if(civLineasCult){ponerAtributo(civLineasCult.geometry,'position',QP,3);ponerAtributo(civLineasCult.geometry,'color',QC,3);civLineasCult.visible=nQ>0;}
  layerMeshes.civils=civFillMesh?[civFillMesh]:[];

  if(faltantes){purgarCivCache();avisarRN({type:'cacheVaciada'});return;}
  // Desalojo parcial: se tiran los territorios que llevan mas tiempo sin
  // usarse y se avisa a React Native de cuales, para que vuelva a mandar sus
  // coordenadas la proxima vez que hagan falta.
  var claves=Object.keys(civCache);
  if(claves.length>CIV_CACHE_MAX){
    var frias=[];
    for(var q2=0;q2<claves.length;q2++)if(!vivos[claves[q2]])frias.push(claves[q2]);
    frias.sort(function(a,b){return civCache[a].uso-civCache[b].uso;});
    var sobran=Math.min(frias.length,claves.length-CIV_CACHE_MAX+100);
    var olvidadas=[];
    for(var w=0;w<sobran;w++){soltarEntrada(civCache[frias[w]]);delete civCache[frias[w]];olvidadas.push(frias[w]);}
    if(olvidadas.length)avisarRN({type:'cacheOlvidado',claves:olvidadas});
  }
}

// Reconstruye los agujeros de un anillo con ranuras (recorte.parte): dos
// paredes verticales a cuatro centesimas, de sentidos opuestos y con altura
// en comun, son una ranura. El arco que cuelga de sus extremos de abajo es el
// agujero; el resto, el contorno. Se repite por si hay varias (o anidadas).
function sanarRanuras(crudo){
  var outer=abreAnillo(crudo), holes=[], guard=0;
  while(guard++<16){
    var n=outer.length, walls=[];
    for(var i=0;i<n;i++){ var a=outer[i], b=outer[(i+1)%n];
      if(Math.abs(a[0]-b[0])<1e-9 && Math.abs(a[1]-b[1])>=0.04) walls.push({i:i,x:a[0],y0:Math.min(a[1],b[1]),y1:Math.max(a[1],b[1]),up:b[1]>a[1]}); }
    var found=null;
    for(var p=0;p<walls.length&&!found;p++)for(var q=p+1;q<walls.length&&!found;q++){
      var A=walls[p],B=walls[q]; var dx=Math.abs(A.x-B.x);
      if(dx<0.03||dx>0.05||A.up===B.up)continue;
      if(Math.min(A.y1,B.y1)-Math.max(A.y0,B.y0)<0.04)continue;
      // los dos arcos entre las paredes: uno es el agujero y el otro el
      // contorno. Se prueba en los dos sentidos y se exige que el agujero
      // sea mas chico y este dentro del contorno; si no, no era una ranura
      // (una astilla de cuatro centesimas de ancho tambien tiene dos paredes)
      var arco=function(desde,hasta){ var o=[], k=(desde+1)%n, c=0; while(c++<=n){ o.push(outer[k]); if(k===hasta)break; k=(k+1)%n; } return o; };
      var a1=arco(A.i,B.i), a2=arco(B.i,A.i);
      var cand=[[a1,a2],[a2,a1]];
      for(var v=0;v<2&&!found;v++){ var h=cand[v][0], o=cand[v][1];
        if(o.length<3)continue;
        // un canal sin agujero al fondo (el agujero se rellenó o se recortó)
        // es una muesca de cuatro centesimas: se cierra y no deja nada
        if(h.length<3){ found=[null,o]; break; }
        var ah=areaPlana(h), ao=areaPlana(o);
        if(ah>=ao*0.8)continue;
        if(!puntoEnAnillo(h[Math.floor(h.length/2)],o))continue;
        found=[h,o]; } }
    if(!found)break;
    if(found[0])holes.push(found[0]); outer=found[1];
  }
  return {outer:outer, holes:holes};
}
function areaPlana(r){ var a=0; for(var i=0,j=r.length-1;i<r.length;j=i++)a+=(r[j][0]+r[i][0])*(r[j][1]-r[i][1]); return Math.abs(a/2); }
function puntoEnAnillo(pt,r){ var d=false; for(var i=0,j=r.length-1;i<r.length;j=i++){ if((r[i][1]>pt[1])!==(r[j][1]>pt[1]) && pt[0]<(r[j][0]-r[i][0])*(pt[1]-r[i][1])/(r[j][1]-r[i][1])+r[i][0]) d=!d; } return d; }
function construirCivil(civ,ringsList){
  var col=new THREE.Color(hexToCol(civ.color));
  // Se elige UN solo anillo para la etiqueta (el de mayor extension), igual
  // que renderCountries: un imperio colonial con metropoli y una docena de
  // colonias no debe repetir su nombre por todo el globo.
  var labelRingIdx=-1,labelRingExtent=-1;
  for(var i=0;i<ringsList.length;i++){
    var rr=ringsList[i],mnx=1e9,mxx=-1e9,mny=1e9,mxy=-1e9;
    for(var q=0;q<rr.length;q++){var pq=rr[q];
      if(pq[0]<mnx)mnx=pq[0];if(pq[0]>mxx)mxx=pq[0];
      if(pq[1]<mny)mny=pq[1];if(pq[1]>mxy)mxy=pq[1];}
    var ext=Math.max(mxx-mnx,mxy-mny);
    if(ext>labelRingExtent){labelRingExtent=ext;labelRingIdx=i;}
  }
  // ── LAS COSTURAS INTERNAS NO SON FRONTERAS ────────────────────────────────
  // Aqui se dibujaba el perimetro COMPLETO de cada anillo, y por eso Estados
  // Unidos aparecia cruzado de lineas rectas de costa a costa.
  //
  // El motivo es que un territorio no es un anillo: son varios. Cuando un
  // poligono tiene un agujero -un enclave, un vecino rodeado-, \`recorte.parte\`
  // lo trocea con cortes verticales en vez de usar el ojo de cerradura, porque
  // las ranuras de ancho cero del keyhole disparan el detector de
  // auto-intersecciones. El troceo es correcto para el relleno y no cuesta
  // nada... salvo que despues alguien dibuje el contorno de cada trozo. Esas
  // lineas verticales no existen en el mundo: son el corte del recortador.
  // Y ademas se pintaban DOS VECES, una por cada trozo, asi que salian al
  // doble de brillo que una frontera de verdad.
  //
  // La regla es exacta y no necesita tolerancia: **una arista que aparece dos
  // veces en el mismo territorio es una junta interna; una que aparece una vez
  // es un borde.** Dos trozos adyacentes comparten la arista del corte con los
  // mismos extremos y en sentido contrario, asi que basta contar aristas con
  // los extremos ordenados. Un borde de verdad -donde el territorio se acaba-
  // no lo recorre nadie mas.
  //
  // Se cuenta sobre los anillos CRUDOS, antes de \`densifyRing\`: densificar
  // primero inserta puntos intermedios que no tienen por que coincidir entre
  // los dos lados y la junta dejaria de reconocerse. Se densifica despues,
  // segmento a segmento, solo lo que se conserva.
  var nEdge=Object.create(null);
  function claveArista(a,b){
    var ka=a[0].toFixed(4)+' '+a[1].toFixed(4), kb=b[0].toFixed(4)+' '+b[1].toFixed(4);
    return ka<kb ? ka+'|'+kb : kb+'|'+ka;
  }
  for(var qi=0;qi<ringsList.length;qi++){
    var qr=ringsList[qi];
    for(var qj=0;qj<qr.length;qj++){
      var qk=claveArista(qr[qj],qr[(qj+1)%qr.length]);
      nEdge[qk]=(nEdge[qk]||0)+1;
    }
  }
  // ── Y LA MITAD DE LAS JUNTAS NO COINCIDEN VERTICE A VERTICE ───────────────
  // Contar aristas iguales solo caza la junta cuando los dos trozos la
  // describen con los mismos extremos, y muchas veces no lo hacen: en Brasil
  // en 1897 el corte de longitud -51,84 aparece en un trozo como el tramo
  // -31,31..-8,63 y en el de al lado como -31,31..-8,60. Son la misma linea y
  // el mismo corte, pero con un vertice de diferencia, asi que la clave no
  // casa. De los 27 cortes verticales de Brasil, la igualdad exacta reconocia
  // 10; los otros 17 se seguian pintando.
  //
  // La prueba que no depende de los vertices es preguntar por el TERRITORIO:
  // **una arista con relleno a los dos lados no es un borde.** Se toma el punto
  // medio, se desplaza un poco a un lado y al otro, y si los dos caen dentro de
  // algun anillo del mismo territorio la arista es interior y no se dibuja.
  //
  // Solo se aplica a tramos rectos y largos -los cortes de \`recorte.parte\` son
  // siempre verticales-, porque ahi esta el problema y porque hacerlo en los
  // 2,7 millones de segmentos del mapa costaria lo que no vale. En un
  // territorio corriente son dos docenas de segmentos.
  function dentroDelTerritorio(px,py){
    for(var m=0;m<ringsList.length;m++){
      var rg=ringsList[m], dd=false;
      for(var u=0,w=rg.length-1;u<rg.length;w=u++){
        if((rg[u][1]>py)!==(rg[w][1]>py) &&
           px < (rg[w][0]-rg[u][0])*(py-rg[u][1])/(rg[w][1]-rg[u][1])+rg[u][0]) dd=!dd;
      }
      if(dd)return true;
    }
    return false;
  }
  function juntaInterior(a,b){
    var dx=b[0]-a[0], dy=b[1]-a[1];
    var len=Math.sqrt(dx*dx+dy*dy);
    if(len<0.1)return false;
    if(Math.abs(dx)>1e-9 && Math.abs(dy)>1e-9)return false;   // ni vertical ni horizontal
    var mx=(a[0]+b[0])/2, my=(a[1]+b[1])/2;
    var nx=-dy/len*0.05, ny=dx/len*0.05;   // mas alla del canal de la ranura (0,04)
    return dentroDelTerritorio(mx+nx,my+ny) && dentroDelTerritorio(mx-nx,my-ny);
  }
  // ── UN CONTORNO QUE NO SE SABE NO SE DIBUJA COMO SI SE SUPIERA ────────────
  //
  // Unos dos mil anillos del mapa tienen firma de forma sintetica: rectangulos,
  // triangulos, elipses, contornos de seis vertices, meridianos exactos de
  // quinientos kilometros en pleno siglo XIII. Para casi todos no hay arreglo
  // posible. Un kanato nomada de la estepa no tiene contorno conocido, y
  // cambiarle el rectangulo por una mancha de aspecto natural no aniade ni un
  // dato: solo hace que el lector crea que el mapa sabe algo que no sabe.
  //
  // Asi que la geometria se queda y lo que cambia es como se dibuja. La
  // herramienta incierto.js marca esos periodos con inc:1 y aqui se pintan con
  // el relleno apagado y el borde a trazos. El territorio sigue donde estaba; lo que
  // desaparece es la afirmacion de que la frontera pasaba exactamente por ahi.
  var inc = !!civ.inc;
  var cult = !!civ.cult;
  var colF = inc ? {r:col.r*0.74+0.05, g:col.g*0.74+0.05, b:col.b*0.74+0.06} : col;
  if(cult) colF = {r:colF.r*0.72, g:colF.g*0.72, b:colF.b*0.72};
  var fp=[],fc=[],lp=[],lc=[],pp=[],pc=[],lq=[],lqc=[],etiqueta=null;
  for(var ri=0;ri<ringsList.length;ri++){
    var crudo=ringsList[ri];
    var san=sanarRanuras(crudo);
    var ring=densifyRing(san.outer,4);
    // Relleno triangulado
    var fv=fillVertsFromRing(ring,1.014,san.holes.map(function(h){return densifyRing(h,4);}));
    for(var a=0;a<fv.length;a++)fp.push(fv[a]);
    for(var b=0;b<fv.length;b+=3){fc.push(colF.r,colF.g,colF.b);}
    // Perimetro como segmentos sueltos: asi varios anillos caben en una sola
    // geometria (un LineStrip solo puede describir una polilinea continua).
    // Solo las aristas que nadie mas comparte, densificadas una a una.
    for(var d=0;d<crudo.length;d++){
      var pa=crudo[d], pb=crudo[(d+1)%crudo.length];
      if(nEdge[claveArista(pa,pb)]>1)continue;          // junta interna, vertices iguales
      if(juntaInterior(pa,pb))continue;                 // junta interna, relleno a los dos lados
      var ddx=pb[0]-pa[0], ddy=pb[1]-pa[1];
      // El borde incierto se trocea mas fino para que el trazo se vea como
      // trazo y no como una linea con mordiscos.
      var largo=Math.sqrt(ddx*ddx+ddy*ddy);
      var pasos=Math.max(1,Math.ceil(largo/(inc?1.2:4)));
      var vprev=ll2v3(pa[1],pa[0],1.014);
      for(var sp=1;sp<=pasos;sp++){
        var t=sp/pasos;
        var vnext=ll2v3(pa[1]+ddy*t, pa[0]+ddx*t, 1.014);
        // a trazos: se salta uno de cada dos tramos
        if(!(inc && (sp%2===0))){
          if(cult){ lq.push(vprev.x,vprev.y,vprev.z,vnext.x,vnext.y,vnext.z); lqc.push(colF.r,colF.g,colF.b,colF.r,colF.g,colF.b); }
          else { lp.push(vprev.x,vprev.y,vprev.z,vnext.x,vnext.y,vnext.z); lc.push(colF.r,colF.g,colF.b,colF.r,colF.g,colF.b); }
        }
        vprev=vnext;
      }
    }
    // ── UNA ISLA DEMASIADO PEQUENA PARA VERSE SIGUE SIENDO UNA ISLA ─────────
    // Los atolones del Pacifico miden diezmilesimas de grado cuadrado: Tarawa
    // tres, las Marshall enteras dos centesimas. A escala de globo eso es menos
    // de un pixel, y por eso durante toda la campana estuvieron dibujados como
    // RECTANGULOS SOBRE MAR ABIERTO. Era la unica forma de que Micronesia y la
    // Polinesia existieran en el mapa, y era falsa: afirmaba que el oceano es
    // territorio. En 1500 el 2,7% de todo lo que el mapa pintaba era mar.
    //
    // La solucion no es mentir en el dato, es marcarlo al pintar. El dato dice
    // la verdad -las islas reales, aunque midan nada- y el renderizador les
    // pone un punto de TAMANO FIJO EN PIXELES, que es lo que hace cualquier
    // atlas con una isla pequena: al alejarse marca la presencia, al acercarse
    // el poligono real lo desborda y toma el relevo. La separacion correcta es
    // esa -el dato afirma, el dibujo comunica- y confundirlas es lo que puso el
    // Pacifico entero dentro del mapa.
    // ── Y EL PUNTO DE PRESENCIA SE RETIRA ─────────────────────────────────
    //
    // La mitad de arriba de este razonamiento sigue en pie y es la que importa:
    // el dato dice la verdad -las islas reales, en su coordenada, aunque midan
    // una diezmilesima de grado cuadrado- y ya no hay un solo rectangulo de
    // oceano pintado como territorio. Eso se queda.
    //
    // Lo que no se sostuvo fue la segunda mitad. Un punto de tamanio fijo por
    // cada islote llena el Pacifico de cuadraditos: las Carolinas solas son
    // treinta, y a escala de globo no dicen de quien son ni que son, solo
    // ensucian. Un atlas pone el punto cuando tiene UNA isla que senialar, no
    // cuando tiene un archipielago entero. Asi que se quita: quien quiera ver
    // Micronesia se acerca, y al acercarse aparece el poligono de verdad.
    //
    // La separacion -el dato afirma, el dibujo comunica- sigue siendo la
    // correcta. Lo que estaba mal era lo que el dibujo comunicaba.
    // El centro de la etiqueta sigue calculandose con el anillo entero: el
    // rotulo va en medio del trozo, lo dibuje o no por fuera.
    var pts=[];
    for(var c=0;c<ring.length;c++)pts.push(ll2v3(ring[c][1],ring[c][0],1.014));
    if(civ.name&&ri===labelRingIdx&&state.showCivilNames){
      var cen=new THREE.Vector3();
      for(var e=0;e<pts.length;e++)cen.add(pts[e]);
      cen.divideScalar(pts.length).normalize().multiplyScalar(1.027);
      var sf=Math.max(0.55,Math.min(1.7,labelRingExtent/30));
      etiqueta=makeTextSprite(civ.name,civLabelColor(civ.color),0.30*sf,'rgba(8,12,18,0.55)');
      etiqueta.position.copy(cen);
      etiqueta.renderOrder=5;
      etiqueta.userData={civId:civ.id};
    }
  }
  return {civId:civ.id,
    fp:new Float32Array(fp),fc:new Float32Array(fc),
    lp:new Float32Array(lp),lc:new Float32Array(lc),
    lq:new Float32Array(lq),lqc:new Float32Array(lqc),
    pp:new Float32Array(pp),pc:new Float32Array(pc),
    etiqueta:etiqueta};
}

function rebuildRoutes(routes){
  layerMeshes.routes.forEach(function(m){procesGroup.remove(m);});layerMeshes.routes=[];
  routeParticles=[];
  if(!state.routes||!routes)return;
  routes.forEach(function(r){
    var col=hexToCol(r.color);
    var pts=r.points.map(function(p){return ll2v3(p[0],p[1],1.030);});
    var curve=new THREE.CatmullRomCurve3(pts);
    var tubGeo=new THREE.TubeGeometry(curve,80,0.005,6,false);
    var tubMat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.70});
    var tube=new THREE.Mesh(tubGeo,tubMat);tube.renderOrder=3;
    tube.userData={routeId:r.id};
    procesGroup.add(tube);layerMeshes.routes.push(tube);
    // Hit-test tube — invisible, much fatter than the visible one (0.005
    // world-units is only a couple of screen pixels, too thin to tap
    // reliably with a finger). Same curve, same routeId, zero opacity: it
    // exists purely to give getTappedRoute() a realistic target area.
    var hitGeo=new THREE.TubeGeometry(curve,80,0.028,6,false);
    var hitMat=new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false});
    var hitTube=new THREE.Mesh(hitGeo,hitMat);hitTube.renderOrder=2;
    hitTube.userData={routeId:r.id};
    procesGroup.add(hitTube);layerMeshes.routes.push(hitTube);
    // Particles — also tagged so tap works on them
    var numP=6;
    for(var i=0;i<numP;i++){
      var pGeo=new THREE.SphereGeometry(0.010,6,6);
      var pMat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.9});
      var pMesh=new THREE.Mesh(pGeo,pMat);
      pMesh.renderOrder=4;
      pMesh.userData={routeId:r.id};
      procesGroup.add(pMesh);layerMeshes.routes.push(pMesh);
      routeParticles.push({mesh:pMesh,curve:curve,phase:i/numP,routeId:r.id});
    }
  });
}

function rebuildWars(wars){
  layerMeshes.wars.forEach(function(m){procesGroup.remove(m);});layerMeshes.wars=[];
  if(!state.wars||!wars)return;
  wars.forEach(function(w){
    var col=hexToCol(w.color);
    var center=ll2v3(w.lat,w.lon,1.026);
    var r=0.005+w.radius*0.006;
    var geo=new THREE.RingGeometry(r*0.7,r,40);
    var mat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.75,side:THREE.DoubleSide});
    var mesh=new THREE.Mesh(geo,mat);
    mesh.position.copy(center);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),center.clone().normalize());
    mesh.userData={warId:w.id};
    mesh.renderOrder=3;procesGroup.add(mesh);layerMeshes.wars.push(mesh);
    var innerGeo=new THREE.CircleGeometry(r*0.7,40);
    var innerMat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.18,side:THREE.DoubleSide});
    var inner=new THREE.Mesh(innerGeo,innerMat);
    inner.position.copy(center);inner.quaternion.copy(mesh.quaternion);
    inner.userData={warId:w.id};
    inner.renderOrder=3;procesGroup.add(inner);layerMeshes.wars.push(inner);
    // Hit area generosa sobre el epicentro — el anillo/círculo son finos y
    // difíciles de tocar con precisión; una esfera invisible más grande
    // facilita el tap sin afectar lo visual.
    var epiHit=new THREE.Mesh(
      new THREE.SphereGeometry(r*1.4,8,8),
      new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false})
    );
    epiHit.position.copy(center);epiHit.userData={warId:w.id};
    procesGroup.add(epiHit);layerMeshes.wars.push(epiHit);

    // Batallas asociadas — pin (más chico y tenue si es 'minor', una
    // batalla no-clave) por cada una, tocable individualmente.
    var battles=w.battles||[];
    battles.forEach(function(b,bi){
      var bPos=ll2v3(b.lat,b.lon,1.026);
      var isMinor=!!b.minor;

      var dot=new THREE.Mesh(
        new THREE.SphereGeometry(isMinor?0.0035:0.006,8,8),
        new THREE.MeshPhongMaterial({color:col,emissive:col,emissiveIntensity:isMinor?0.55:1.0,transparent:true,opacity:isMinor?0.60:0.92})
      );
      dot.position.copy(bPos);
      dot.userData={warId:w.id,battleIdx:bi};
      dot.renderOrder=4;procesGroup.add(dot);layerMeshes.wars.push(dot);

      var bHit=new THREE.Mesh(
        new THREE.SphereGeometry(0.020,8,8),
        new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false})
      );
      bHit.position.copy(bPos);
      bHit.userData={warId:w.id,battleIdx:bi};
      procesGroup.add(bHit);layerMeshes.wars.push(bHit);
    });

    // Trayectoria punteada: conecta las batallas en ORDEN CRONOLÓGICO (no
    // el orden en que aparecen en el array de datos) mediante segmentos
    // interpolados sobre la esfera (slerp), para que se entienda cómo se
    // movió el conflicto en el mapa. Reemplaza los antiguos "radios" rectos
    // desde el epicentro a cada batalla (quedaban desordenados y no
    // contaban una trayectoria real). Solo tiene sentido con 2+ batallas.
    if(battles.length>1){
      var sorted=battles.map(function(b,bi){return {b:b,bi:bi};}).sort(function(x,y){return x.b.year-y.b.year;});
      var allPts=[];
      for(var si=0;si<sorted.length-1;si++){
        var pA=ll2v3(sorted[si].b.lat,sorted[si].b.lon,1.027);
        var pB=ll2v3(sorted[si+1].b.lat,sorted[si+1].b.lon,1.027);
        var segCount=Math.max(4,Math.round(pA.angleTo(pB)*24));
        var segPts=slerpPoints(pA,pB,segCount,1.027);
        if(si>0)segPts.shift(); // no duplicar el punto de unión compartido
        allPts=allPts.concat(segPts);
      }
      var trajGeo=new THREE.BufferGeometry().setFromPoints(allPts);
      var trajMat=new THREE.LineDashedMaterial({color:col,transparent:true,opacity:0.55,dashSize:0.012,gapSize:0.009});
      var traj=new THREE.Line(trajGeo,trajMat);
      traj.computeLineDistances();
      traj.renderOrder=3;procesGroup.add(traj);layerMeshes.wars.push(traj);
    }
  });
}

// ── Migration particles state ─────────────────────────────────────────────────
var migrationParticles=[];

function rebuildMigration(flows){
  layerMeshes.migration.forEach(function(m){procesGroup.remove(m);});
  layerMeshes.migration=[];
  migrationParticles=[];
  if(!state.migration||!flows||!flows.length)return;

  flows.forEach(function(f){
    var col=hexToCol(f.color);
    var isSea=f.type==='sea';
    var pts=f.waypoints.map(function(p){return ll2v3(p.lat,p.lon,1.034);});
    var curve=new THREE.CatmullRomCurve3(pts,false,'catmullrom',0.5);

    // Hit-test tube — invisible, covers the WHOLE path. Before this, the
    // only tappable geometry was the handful of small animated icons
    // (4-6 ships/footprints per flow) — most of the path had literally
    // nothing to tap. Same idea as the routes fix above: a fat, invisible
    // tube along the curve tagged with migId, picked up by getTappedMigration().
    var hitGeo=new THREE.TubeGeometry(curve,100,0.030,6,false);
    var hitMat=new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false});
    var hitTube=new THREE.Mesh(hitGeo,hitMat);hitTube.renderOrder=2;
    hitTube.userData={migId:f.id};
    procesGroup.add(hitTube);layerMeshes.migration.push(hitTube);

    // ── Route line — dashed-looking via segments ──────────────────────────────
    var linePts=curve.getPoints(120);
    // Draw as alternating visible/gap segments for a dashed effect
    for(var seg=0;seg<linePts.length-1;seg+=2){
      var segGeo=new THREE.BufferGeometry().setFromPoints([linePts[seg],linePts[seg+1]]);
      var segMat=new THREE.LineBasicMaterial({
        color:col, transparent:true,
        opacity: isSea ? 0.55 : 0.50,
      });
      var segLine=new THREE.Line(segGeo,segMat);
      segLine.renderOrder=3;
      procesGroup.add(segLine);layerMeshes.migration.push(segLine);
    }

    // ── Animated icons ────────────────────────────────────────────────────────
    var numIcons=isSea ? 4 : 6;
    for(var i=0;i<numIcons;i++){
      if(isSea){
        // Ship: hull + mast + sail
        var shipGroup=new THREE.Group();

        var hullGeo=new THREE.SphereGeometry(1,8,4);
        hullGeo.scale(0.016,0.005,0.007);
        var hullMat=new THREE.MeshPhongMaterial({
          color:col,transparent:true,opacity:0.82,
          emissive:col,emissiveIntensity:0.25,shininess:40,
        });
        var hull=new THREE.Mesh(hullGeo,hullMat);
        hull.renderOrder=6;
        shipGroup.add(hull);

        var mastGeo=new THREE.CylinderGeometry(0.0010,0.0010,0.022,4);
        var mastMat=new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:0.70});
        var mast=new THREE.Mesh(mastGeo,mastMat);
        mast.position.y=0.011;
        mast.renderOrder=6;
        shipGroup.add(mast);

        var sailGeo=new THREE.ConeGeometry(0.007,0.016,4);
        var sailMat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.80,side:THREE.DoubleSide});
        var sail=new THREE.Mesh(sailGeo,sailMat);
        sail.position.y=0.020;
        sail.renderOrder=6;
        shipGroup.add(sail);

        var wakeMat2=new THREE.MeshBasicMaterial({color:0x88ccff,transparent:true,opacity:0.35,depthWrite:false});
        var wake1=new THREE.Mesh(new THREE.SphereGeometry(0.004,4,4),wakeMat2);
        var wake2=new THREE.Mesh(new THREE.SphereGeometry(0.003,4,4),wakeMat2.clone());
        wake1.renderOrder=5;wake2.renderOrder=5;

        procesGroup.add(shipGroup);
        procesGroup.add(wake1);
        procesGroup.add(wake2);
        layerMeshes.migration.push(shipGroup,wake1,wake2);
        shipGroup.userData={migId:f.id};
        migrationParticles.push({mesh:shipGroup,wake1:wake1,wake2:wake2,curve:curve,phase:i/numIcons,isSea:true});

      } else {
        // Footprints: pair of ovals
        var footGroup=new THREE.Group();

        var footMat=new THREE.MeshPhongMaterial({
          color:col,transparent:true,opacity:0.80,
          emissive:col,emissiveIntensity:0.35,
        });
        var lGeo=new THREE.SphereGeometry(1,6,4);lGeo.scale(0.006,0.002,0.010);
        var lFoot=new THREE.Mesh(lGeo,footMat);lFoot.position.x=-0.010;lFoot.renderOrder=6;footGroup.add(lFoot);

        var rGeo=new THREE.SphereGeometry(1,6,4);rGeo.scale(0.006,0.002,0.010);
        var rFoot=new THREE.Mesh(rGeo,footMat.clone());rFoot.position.x=0.010;rFoot.renderOrder=6;footGroup.add(rFoot);

        var glowGeo=new THREE.SphereGeometry(0.014,6,4);
        var glowMat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.13,depthWrite:false,blending:THREE.AdditiveBlending});
        var glow=new THREE.Mesh(glowGeo,glowMat);glow.renderOrder=5;footGroup.add(glow);

        procesGroup.add(footGroup);
        footGroup.userData={migId:f.id};
        layerMeshes.migration.push(footGroup);
        migrationParticles.push({mesh:footGroup,wake1:null,wake2:null,curve:curve,phase:i/numIcons,isSea:false,hopOffset:i*0.7});
      }
    }

    // ── Origin pulse ring ─────────────────────────────────────────────────────
    var originPos=pts[0];
    var pRing=new THREE.Mesh(
      new THREE.RingGeometry(0.014,0.022,16),
      new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.70,side:THREE.DoubleSide,depthWrite:false})
    );
    pRing.position.copy(originPos);
    pRing.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),originPos.clone().normalize());
    pRing.renderOrder=4;
    procesGroup.add(pRing);layerMeshes.migration.push(pRing);

    // ── Destination arrow-like dot ────────────────────────────────────────────
    var destPos=pts[pts.length-1];
    var destDot=new THREE.Mesh(
      new THREE.SphereGeometry(0.014,8,8),
      new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.80,blending:THREE.AdditiveBlending,depthWrite:false})
    );
    destDot.position.copy(destPos);destDot.renderOrder=4;
    procesGroup.add(destDot);layerMeshes.migration.push(destDot);
  });
}

function rebuildReligion(religions){
  layerMeshes.religion.forEach(function(m){procesGroup.remove(m);});layerMeshes.religion=[];
  if(!state.religion||!religions)return;
  religions.forEach(function(rel){
    var col=hexToCol(rel.color);
    // Una religión puede tener varias regiones disjuntas en el mismo periodo
    // (ej. catolicismo: Europa + América Latina + Filipinas) -- un ring por
    // país/grupo de países real, igual que rebuildCivils.
    var ringsList=rel.rings||(rel.ring?[rel.ring]:[]);
    ringsList.forEach(function(rawRing){
      var ring=densifyRing(rawRing,4);
      var pts=ring.map(function(p){return ll2v3(p[1],p[0],1.018);});

      // Centro (para el punto de tap) y relleno via triangulación real (ear clipping)
      var centroid=new THREE.Vector3();
      pts.forEach(function(p){centroid.add(p);});
      centroid.divideScalar(pts.length).normalize().multiplyScalar(1.018);

      var fillVerts=fillVertsFromRing(ring,1.018);
      var fillGeo=new THREE.BufferGeometry();
      fillGeo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(fillVerts),3));
      var fillMat=new THREE.MeshBasicMaterial({
        color:col,transparent:true,opacity:0.28,
        side:THREE.DoubleSide,depthWrite:false,
        blending:THREE.AdditiveBlending,
      });
      var fill=new THREE.Mesh(fillGeo,fillMat);
      fill.renderOrder=2;
      fill.userData={religionId:rel.id};
      procesGroup.add(fill);layerMeshes.religion.push(fill);

      // Border outline
      var linePts=pts.concat([pts[0]]);
      var lineGeo=new THREE.BufferGeometry().setFromPoints(linePts);
      var line=new THREE.Line(lineGeo,new THREE.LineBasicMaterial({
        color:col,opacity:0.70,transparent:true,
      }));
      // Sin religionId aquí — mismo motivo que en rebuildLanguages: el fill
      // (arriba) ya cubre el área tocable con intersección de rayo real.
      line.renderOrder=3;
      procesGroup.add(line);layerMeshes.religion.push(line);

      // Center dot for tapping
      var dotGeo=new THREE.SphereGeometry(0.016,8,8);
      var dotMat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.75,blending:THREE.AdditiveBlending,depthWrite:false});
      var dot=new THREE.Mesh(dotGeo,dotMat);
      dot.position.copy(centroid);dot.renderOrder=4;
      dot.userData={religionId:rel.id};
      procesGroup.add(dot);layerMeshes.religion.push(dot);
    });
  });
}

function rebuildLanguages(langs){
  layerMeshes.languages.forEach(function(m){procesGroup.remove(m);});layerMeshes.languages=[];
  if(!state.languages||!langs)return;
  langs.forEach(function(lang){
    var col=hexToCol(lang.color);
    // Un idioma puede tener varias regiones disjuntas en el mismo periodo
    // (ej. portugués: Portugal + Brasil + Angola + Mozambique) -- un ring
    // por país/grupo de países real, igual que rebuildCivils.
    var ringsList=lang.rings||(lang.ring?[lang.ring]:[]);
    ringsList.forEach(function(rawRing){
      var ring=densifyRing(rawRing,4);
      var pts=ring.map(function(p){return ll2v3(p[1],p[0],1.022);});

      // Centro (para el punto de tap) y relleno via triangulación real (ear clipping)
      var centroid=new THREE.Vector3();
      pts.forEach(function(p){centroid.add(p);});
      centroid.divideScalar(pts.length).normalize().multiplyScalar(1.022);

      var fillVerts=fillVertsFromRing(ring,1.022);
      var fillGeo=new THREE.BufferGeometry();
      fillGeo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(fillVerts),3));
      var fillMat=new THREE.MeshBasicMaterial({
        color:col,transparent:true,opacity:0.30,
        side:THREE.DoubleSide,depthWrite:false,
        blending:THREE.AdditiveBlending,
      });
      var fill=new THREE.Mesh(fillGeo,fillMat);
      fill.renderOrder=2;
      fill.userData={langId:lang.id};
      procesGroup.add(fill);layerMeshes.languages.push(fill);

      // Border outline
      var linePts=pts.concat([pts[0]]);
      var lineGeo=new THREE.BufferGeometry().setFromPoints(linePts);
      var line=new THREE.Line(lineGeo,new THREE.LineBasicMaterial({
        color:col,opacity:0.75,transparent:true,
      }));
      // Sin langId aquí — mismo motivo que en rebuildCivils: el umbral de
      // distancia por defecto del Raycaster para Line es enorme frente al
      // globo y puede robar el tap a favor de un borde ajeno. El fill (arriba)
      // ya cubre el área tocable con intersección de rayo real y precisa.
      line.renderOrder=3;
      procesGroup.add(line);layerMeshes.languages.push(line);

      // Center dot for tapping
      var dotGeo=new THREE.SphereGeometry(0.018,8,8);
      var dotMat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.70,blending:THREE.AdditiveBlending,depthWrite:false});
      var dot=new THREE.Mesh(dotGeo,dotMat);
      dot.position.copy(centroid);dot.renderOrder=4;
      dot.userData={langId:lang.id};
      procesGroup.add(dot);layerMeshes.languages.push(dot);
    });
  });
}

// Wonders of the world -- point landmarks (pirámides, templos, ruinas...)
// shown as small "figurine" glyphs. Toggled from the Divisiones drawer
// section like mountains/rivers/deserts, but -- unlike those, which are
// static geography -- each wonder only exists on screen while the current
// year falls within its real lifespan (built..destroyed), so the data is
// computed year-by-year on the RN side (getActiveWonders) and arrives here
// through the same 'updateProcesses' pipe as civilizations/routes/etc.
// rather than the static 'updateDivisions' one.
// Custom hand-picked icon images (base64 PNG, background already made
// transparent) for wonders the user supplied artwork for -- falls back to
// the procedural makeWonderGlyph()/makeSatelliteSprite() silhouettes for
// any wonder id not present here.
var WONDER_ICONS={
  christ_redeemer:'data:image/png;base64,',
  easter_island:'data:image/png;base64,',
  panama_canal:'data:image/png;base64,',
  suez_canal:'data:image/png;base64,',
  taj_mahal:'data:image/png;base64,',
  angkor_wat:'data:image/png;base64,',
  artemis_ephesus:'data:image/png;base64,',
  borobudur:'data:image/png;base64,',
  chichen_itza:'data:image/png;base64,',
  colosseum:'data:image/png;base64,',
  colossus_rhodes:'data:image/png;base64,',
  great_wall:'data:image/png;base64,',
  great_zimbabwe:'data:image/png;base64,',
  hanging_gardens:'data:image/png;base64,',
  iss:'data:image/png;base64,',
  lighthouse_alexandria:'data:image/png;base64,',
  machu_picchu:'data:image/png;base64,',
  mausoleum_halicarnassus:'data:image/png;base64,',
  parthenon:'data:image/png;base64,',
  persepolis:'data:image/png;base64,',
  petra:'data:image/png;base64,',
  stonehenge:'data:image/png;base64,',
  teotihuacan:'data:image/png;base64,',
  zeus_olympia:'data:image/png;base64,',
};

var _wonderIconTexCache={};
function getWonderIconTexture(id){
  if(_wonderIconTexCache[id])return _wonderIconTexCache[id];
  var url=WONDER_ICONS[id];
  if(!url)return null;
  var tex=new THREE.TextureLoader().load(url);
  _wonderIconTexCache[id]=tex;
  return tex;
}
function makeWonderImageSprite(id,size){
  var tex=getWonderIconTexture(id);
  var mat=new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false});
  var sprite=new THREE.Sprite(mat);
  sprite.scale.set(size,size,1);
  return sprite;
}


function rebuildWonders(wonders){
  layerMeshes.wonders.forEach(function(m){procesGroup.remove(m);});layerMeshes.wonders=[];
  if(!state.wonders||!wonders)return;
  var wonderColor='#D4AF37';
  wonders.forEach(function(w){
    // Most wonders are a single point -- a small figurine glyph. A few
    // (e.g. the Great Wall) are given a 'pts' path instead and are drawn
    // as a full line covering their real extent (same TubeGeometry
    // technique as renderRivers), so it reads as "the whole wall" rather
    // than one arbitrary spot on it. Both cases tag their meshes with the
    // same userData.wonderId, so getTappedWonder()/'wonderTap' -- and the
    // info-card lookup by id -- work identically either way.
    if(w.pts&&w.pts.length>1){
      var pts3=w.pts.map(function(p){return ll2v3(p[1],p[0],1.020);});
      var curve=new THREE.CatmullRomCurve3(pts3);
      var segs=Math.max(40,w.pts.length*8);
      var tubGeo=new THREE.TubeGeometry(curve,segs,0.0044,6,false);
      var tubMat=new THREE.MeshBasicMaterial({color:wonderColor,transparent:true,opacity:0.9});
      var tube=new THREE.Mesh(tubGeo,tubMat);
      tube.renderOrder=10;tube.userData={wonderId:w.id};
      procesGroup.add(tube);layerMeshes.wonders.push(tube);

      var hitGeo=new THREE.TubeGeometry(curve,segs,0.024,6,false);
      var hitMat=new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false});
      var hitTube=new THREE.Mesh(hitGeo,hitMat);
      hitTube.renderOrder=9;hitTube.userData={wonderId:w.id};
      procesGroup.add(hitTube);layerMeshes.wonders.push(hitTube);

      if(state.wonders_names){
        var midp=w.pts[Math.floor(w.pts.length/2)];
        var spp=makeTextSprite(w.name,'rgba(212,175,55,0.92)',0.24);
        spp.position.copy(ll2v3(midp[1],midp[0],1.036));
        spp.renderOrder=11;spp.userData={wonderId:w.id};
        procesGroup.add(spp);layerMeshes.wonders.push(spp);
      }
      // The line itself covers the wall's real extent, but still gets an
      // icon glyph anchored at lat/lon (e.g. Badaling) so it reads as a
      // "figurine" landmark too, same as the point-based wonders below.
      if(WONDER_ICONS[w.id]){
        var wallIcon=makeWonderImageSprite(w.id,0.06);
        wallIcon.position.copy(ll2v3(w.lat,w.lon,1.026));
        wallIcon.renderOrder=10;wallIcon.userData={wonderId:w.id};
        procesGroup.add(wallIcon);layerMeshes.wonders.push(wallIcon);
      }
      return;
    }

    // The ISS (and any other future orbital marker) floats above the
    // surface instead of sitting on it, since it isn't a ground structure.
    var isSpace=w.type==='space';
    var glyphR=isSpace?1.14:1.024;
    var pos=ll2v3(w.lat,w.lon,glyphR);
    // Prefer the user-supplied icon image when we have one for this wonder;
    // otherwise fall back to the hand-drawn procedural silhouette (or the
    // satellite glyph for orbital markers with no image yet).
    var glyph=WONDER_ICONS[w.id]
      ? makeWonderImageSprite(w.id, isSpace?0.062:0.056)
      : (isSpace?makeSatelliteSprite('#D4AF37',0.058):makeWonderGlyph(w.shape,wonderColor,0.052));
    glyph.position.copy(pos);
    glyph.renderOrder=10;glyph.userData={wonderId:w.id};
    procesGroup.add(glyph);layerMeshes.wonders.push(glyph);

    // Generous invisible hit-sphere -- the glyph itself is a thin sprite,
    // hard to tap precisely with a finger.
    var hit=new THREE.Mesh(
      new THREE.SphereGeometry(0.026,8,8),
      new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false})
    );
    hit.position.copy(pos);hit.userData={wonderId:w.id};
    procesGroup.add(hit);layerMeshes.wonders.push(hit);

    if(state.wonders_names){
      var sp=makeTextSprite(w.name,'rgba(212,175,55,0.92)',0.24);
      sp.position.copy(ll2v3(w.lat,w.lon,glyphR+0.014));
      sp.renderOrder=11;sp.userData={wonderId:w.id};
      procesGroup.add(sp);layerMeshes.wonders.push(sp);
    }
  });
}

// ── Interaction ───────────────────────────────────────────────────────────────
var isDragging=false,lastX=0,lastY=0,lastMs=0;
var velX=0,velY=0;
var targetRotX=0,targetRotY=0;
var pinchDist=null;
var targetScale=1.0,currentScale=1.0;
var tapStartX=null,tapStartY=null,tapStartMs=0;
var raycaster=new THREE.Raycaster();
var mouse=new THREE.Vector2();

function getTappedPin(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  var dotMeshes=pinMeshes.filter(function(m){return m.userData&&m.userData.id;});
  var hits=raycaster.intersectObjects(dotMeshes,false);
  if(hits.length>0)return hits[0].object.userData.id;
  return null;
}

function getTappedWar(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  var warMeshes=layerMeshes.wars.filter(function(m){return m.userData&&m.userData.warId;});
  var hits=raycaster.intersectObjects(warMeshes,false);
  if(hits.length>0){
    var ud=hits[0].object.userData;
    return { warId:ud.warId, battleIdx:(ud.battleIdx!==undefined?ud.battleIdx:null) };
  }
  return null;
}

function getTappedRoute(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  var routeMeshes=layerMeshes.routes.filter(function(m){return m.userData&&m.userData.routeId;});
  var hits=raycaster.intersectObjects(routeMeshes,false);
  if(hits.length>0)return hits[0].object.userData.routeId;
  return null;
}

function getTappedMigration(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  // Invisible hit-tubes (whole path, see rebuildMigration) + the small
  // animated icons (ships/footprints) — both count as valid tap targets.
  var migMeshes=layerMeshes.migration.filter(function(m){return m.userData&&m.userData.migId;});
  migrationParticles.forEach(function(mp){
    if(mp.mesh&&mp.mesh.userData&&mp.mesh.userData.migId){
      migMeshes.push(mp.mesh);
    }
  });
  var hits=raycaster.intersectObjects(migMeshes,true);
  if(hits.length>0){
    var obj=hits[0].object;
    while(obj.parent&&!obj.userData.migId)obj=obj.parent;
    return obj.userData.migId||null;
  }
  return null;
}

function getTappedLanguage(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  var langMeshes=layerMeshes.languages.filter(function(m){return m.userData&&m.userData.langId;});
  var hits=raycaster.intersectObjects(langMeshes,false);
  if(hits.length>0)return hits[0].object.userData.langId;
  return null;
}

function getTappedReligion(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  var relMeshes=layerMeshes.religion.filter(function(m){return m.userData&&m.userData.religionId;});
  var hits=raycaster.intersectObjects(relMeshes,false);
  if(hits.length>0)return hits[0].object.userData.religionId;
  return null;
}

function getTappedCivil(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  // Toda la capa es UNA malla fusionada, asi que el civId no puede ir en el
  // objeto: se guarda por triangulo en civTriIds y se resuelve con el
  // faceIndex del impacto.
  if(!civFillMesh||!civFillMesh.visible)return null;
  var hits=raycaster.intersectObject(civFillMesh,false);
  for(var h=0;h<hits.length;h++){
    var fi=hits[h].faceIndex;
    if(fi!=null&&civTriIds[fi])return civTriIds[fi];
  }
  return null;
}

function getTappedRiver(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  var riverMeshes=divMeshes.filter(function(m){return m.userData&&m.userData.riverId;});
  var hits=raycaster.intersectObjects(riverMeshes,false);
  if(hits.length>0)return hits[0].object.userData.riverId;
  return null;
}

function getTappedWonder(tx,ty){
  mouse.x=(tx/W)*2-1;mouse.y=-(ty/H)*2+1;
  raycaster.setFromCamera(mouse,camera);
  var wonderMeshes=layerMeshes.wonders.filter(function(m){return m.userData&&m.userData.wonderId;});
  var hits=raycaster.intersectObjects(wonderMeshes,false);
  if(hits.length>0)return hits[0].object.userData.wonderId;
  return null;
}

document.addEventListener('touchstart',function(e){
  e.preventDefault();
  if(e.touches.length===2){
    var dx=e.touches[0].clientX-e.touches[1].clientX;
    var dy=e.touches[0].clientY-e.touches[1].clientY;
    pinchDist=Math.sqrt(dx*dx+dy*dy);isDragging=false;
  }else{
    isDragging=true;pinchDist=null;
    lastX=e.touches[0].clientX;lastY=e.touches[0].clientY;lastMs=Date.now();
    tapStartX=lastX;tapStartY=lastY;tapStartMs=lastMs;velX=0;velY=0;
  }
},{passive:false});

document.addEventListener('touchmove',function(e){
  e.preventDefault();tapStartX=null;
  var now=Date.now();
  if(e.touches.length===2&&pinchDist!==null){
    isDragging=false;
    var dx=e.touches[0].clientX-e.touches[1].clientX;
    var dy=e.touches[0].clientY-e.touches[1].clientY;
    var dist=Math.sqrt(dx*dx+dy*dy);
    var newScale=targetScale*(dist/pinchDist);
    // En 2D el alejamiento maximo es justo la escala a la que el mapa entero
    // cabe en pantalla; por debajo de eso el gesto sale al modo orbital.
    var topeMin=MAP2D?vista2D().fit:0.25;
    if(newScale<topeMin*0.88){
      window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'zoomOutExit'}));
      return;
    }
    targetScale=Math.max(topeMin,Math.min(1.8,newScale));pinchDist=dist;return;
  }
  if(e.touches.length===1&&isDragging){
    var dx2=e.touches[0].clientX-lastX;var dy2=e.touches[0].clientY-lastY;
    var dtMs=Math.max(now-lastMs,8);
    // Sensibilidad inversamente proporcional al zoom — más zoom = más suave
    var sens=0.004/Math.max(1,currentScale*currentScale);
    var sensX=sens*0.5; // eje vertical siempre más suave (polos fijos)
    if(MAP2D){
      // Modo 2D: arrastrar desplaza (pan) el mapa en vez de rotar el globo.
      // Un pixel de dedo mueve el mapa exactamente un pixel: la conversion es
      // el ancho visible del mundo dividido entre el ancho de la pantalla.
      var v2=vista2D();
      var wpp=(2*v2.hw)/Math.max(1,W);
      panTX+=dx2*wpp;panTY-=dy2*wpp;
      // El borde del mapa nunca entra en la pantalla; si el mapa cabe entero,
      // el limite es cero y queda centrado.
      var limX=Math.max(0,2*currentScale-v2.hw), limY=Math.max(0,currentScale-v2.hh);
      panTX=Math.max(-limX,Math.min(limX,panTX));
      panTY=Math.max(-limY,Math.min(limY,panTY));
      velX=(dx2*wpp)/(dtMs/1000)*0.35;velY=(-dy2*wpp)/(dtMs/1000)*0.35;
    }else{
      targetRotY+=dx2*sens;targetRotX+=dy2*sensX;
      velX=(dx2*sens)/(dtMs/1000)*0.5;velY=(dy2*sensX)/(dtMs/1000)*0.5;
    }
    lastX=e.touches[0].clientX;lastY=e.touches[0].clientY;lastMs=now;
  }
},{passive:false});

document.addEventListener('touchend',function(e){
  if(e.touches.length<2)pinchDist=null;
  if(e.touches.length===0){
    if(tapStartX!==null&&(Date.now()-tapStartMs)<280){
      var pinId=getTappedPin(tapStartX,tapStartY);
      if(pinId){
        window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'pinTap',id:pinId}));
      }else{
        var warHit=getTappedWar(tapStartX,tapStartY);
        if(warHit){
          window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'warTap',id:warHit.warId,battleIdx:warHit.battleIdx}));
        }else{
        var routeId=getTappedRoute(tapStartX,tapStartY);
        if(routeId){
          window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'routeTap',id:routeId}));
        }else{
          var migId=getTappedMigration(tapStartX,tapStartY);
          if(migId){
            window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'migrationTap',id:migId}));
          }else{
            var langId=getTappedLanguage(tapStartX,tapStartY);
            if(langId){
              window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'languageTap',id:langId}));
            }else{
              var religionId=getTappedReligion(tapStartX,tapStartY);
              if(religionId){
                window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'religionTap',id:religionId}));
              }else{
                var civId=getTappedCivil(tapStartX,tapStartY);
                if(civId){
                  window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'civilizationTap',id:civId}));
                }else{
                  var riverId=getTappedRiver(tapStartX,tapStartY);
                  if(riverId){
                    window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'riverTap',id:riverId}));
                  }else{
                    var wonderId=getTappedWonder(tapStartX,tapStartY);
                    if(wonderId)window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(JSON.stringify({type:'wonderTap',id:wonderId}));
                  }
                }
              }
            }
          }
        }
        }
      }
    }
    isDragging=false;tapStartX=null;
  }
},{passive:false});

// ── Message handler ───────────────────────────────────────────────────────────
document.addEventListener('message',handleRNMsg);
window.addEventListener('message',handleRNMsg);
function handleRNMsg(e){
  try{
    var msg=JSON.parse(e.data);
    if(msg.type==='updatePins'){PINS=msg.pins;console.log('PINS recibidos:',PINS.length);buildPins();}
    else if(msg.type==='rotateTo'){
      if(MAP2D){
        // Centrar el punto en el plano: la escala del grupo multiplica las
        // coordenadas de los hijos, así que el pan se compensa por ella
        targetScale=1.4;
        panTX=-(msg.lon/90)*targetScale;
        panTY=-(msg.lat/90)*targetScale;
      }else{
      var phi=(msg.lon+180)*Math.PI/180;
      var rawRotY=Math.PI/2-phi;
      var curY=globeGroup.rotation.y;
      var diff=((rawRotY-curY)%(Math.PI*2)+Math.PI*3)%(Math.PI*2)-Math.PI;
      targetRotY=curY+diff;
      targetRotX=(msg.lat*Math.PI/180)-0.15;
      targetScale=1.4;
      }
    }
    else if(msg.type==='baseTierra'){ baseTierraRings=msg.rings||[]; construirBaseTierra(); }
    else if(msg.type==='revSave'){ try{localStorage.setItem('bluedot_rev',msg.data);}catch(e){} }
    else if(msg.type==='revLoad'){ var revD=null; try{revD=localStorage.getItem('bluedot_rev');}catch(e){} avisarRN({type:'revData',data:revD}); }
    else if(msg.type==='resetGlobe'){
      targetRotX=0;targetRotY=0;velX=0;velY=0;panTX=0;panTY=0;
      targetScale=MAP2D?vista2D().fit:1.0;
    }
    else if(msg.type==='lockRotation'){
      // Called when an event card opens: freeze inertia and auto-spin
      velX=0;velY=0;
      rotationLocked=true;
    }
    else if(msg.type==='unlockRotation'){
      rotationLocked=false;
    }
    else if(msg.type==='setAutoRotate'){
      // Persistent user preference (drawer toggle) -- independent of
      // rotationLocked, which is a transient lock used while a card is
      // open. Only disables the idle auto-spin; manual drag/flick
      // interaction and its momentum decay keep working either way.
      autoSpinStopped=!msg.enabled;
    }
    else if(msg.type==='updateProcesses'){
      lastProcMsg=msg;
      applyProcesses(msg);
    }
    else if(msg.type==='updateDivisions'){
      lastDivLayers=msg.layers||{};
      buildDivisions(lastDivLayers);
    }
    else if(msg.type==='setMapMode'){
      // Alterna entre el globo 3D y la proyección plana 2D. Toda la
      // geometría se reconstruye con ll2v3 en el modo nuevo.
      MAP2D=!!msg.flat;
      panTX=0;panTY=0;panX=0;panY=0;
      targetRotX=0;targetRotY=0;velX=0;velY=0;
      // Al pasar a 2D se entra viendo el mapa completo y centrado
      targetScale=MAP2D?vista2D().fit:1.0;
      currentScale=targetScale;
      applyMapMode();
      rebuildAllLayers();
    }
  }catch(_){}
}

