// ─── Info section icon renderer ──────────────────────────────────────────────
function InfoSectionIcon({ id }) {
  const props = { size:18, color:'rgba(255,255,255,0.7)', weight:'regular' };
  const map = {
    tag:     <Tag     {...props} />,
    planet:  <Planet  {...props} />,
    book:    <BookOpen {...props} />,
    books:   <Books   {...props} />,
    search:  <MagnifyingGlass {...props} />,
    warning: <Warning {...props} />,
    heart:   <Heart   {...props} />,
  };
  return map[id] || null;
}

