const REV_VEREDICTOS = [
  { v:'bien', label:'Bien',  color:'#1D9E75' },
  { v:'mal',  label:'Mal',   color:'#D85A30' },
  { v:'duda', label:'No sé', color:'#EF9F27' },
];
const revColor = (v) => (REV_VEREDICTOS.find(x => x.v === v) || {}).color || 'rgba(255,255,255,0.35)';

function RevisionBar({ idx, data, aislar, onPrev, onNext, onVeredicto, onNota, onAislar, onLista, onFicha, onSalir }) {
  const { formatYear, calendar } = useContext(SettingsContext);
  const e = REVISION_ORDEN[idx];
  const civ = CIVILIZATIONS.find(c => c.id === e[0]);
  const nombre = civ ? (civ.etiqueta || civ.name) : e[0];
  const d = data[e[0]];
  const hechas = Object.keys(data).filter(k => data[k] && data[k].v).length;
  const pct = Math.round(hechas * 100 / REVISION_ORDEN.length);
  return (
    <View style={revSt.bar}>
      <View style={revSt.fila}>
        <TouchableOpacity style={revSt.btnSec} onPress={onPrev}>
          <CaretLeft size={16} color="rgba(255,255,255,0.7)" weight="bold" />
        </TouchableOpacity>
        <Pressable style={{ flex:1, alignItems:'center' }} onPress={onFicha}>
          <Text style={revSt.nombre} numberOfLines={1}>{nombre}</Text>
          <Text style={revSt.sub} numberOfLines={1}>
            {(idx + 1) + ' / ' + REVISION_ORDEN.length + '  ·  ' + formatYear(e[2], calendar) + (e[5] ? '  ·  área cultural' : '') + '  ·  ' + pct + '%'}
          </Text>
        </Pressable>
        <TouchableOpacity style={revSt.btnSec} onPress={onNext}>
          <CaretRight size={16} color="rgba(255,255,255,0.7)" weight="bold" />
        </TouchableOpacity>
      </View>
      <View style={revSt.fila}>
        {REV_VEREDICTOS.map(x => {
          const on = d && d.v === x.v;
          return (
            <TouchableOpacity key={x.v} style={[revSt.btnVer, { borderColor: x.color + (on ? 'ff' : '66'), backgroundColor: on ? x.color + '44' : 'rgba(255,255,255,0.04)' }]}
              onPress={() => onVeredicto(x.v)}>
              {x.v === 'bien' && <Check size={16} color={x.color} weight="bold" />}
              {x.v === 'mal'  && <X size={16} color={x.color} weight="bold" />}
              {x.v === 'duda' && <Question size={16} color={x.color} weight="bold" />}
              <Text style={[revSt.btnVerTxt, { color: x.color }]}>{x.label}</Text>
            </TouchableOpacity>
          );
        })}
        <TouchableOpacity style={[revSt.btnSec, d && d.n ? revSt.btnSecOn : null]} onPress={onNota}>
          <NotePencil size={16} color={d && d.n ? '#378ADD' : 'rgba(255,255,255,0.7)'} weight="regular" />
        </TouchableOpacity>
        <TouchableOpacity style={[revSt.btnSec, aislar && revSt.btnSecOn]} onPress={onAislar}>
          {aislar ? <EyeSlash size={16} color="#378ADD" weight="regular" /> : <Eye size={16} color="rgba(255,255,255,0.7)" weight="regular" />}
        </TouchableOpacity>
        <TouchableOpacity style={revSt.btnSec} onPress={onLista}>
          <ListChecks size={16} color="rgba(255,255,255,0.7)" weight="regular" />
        </TouchableOpacity>
        <TouchableOpacity style={revSt.btnSec} onPress={onSalir}>
          <SignOut size={16} color="rgba(255,255,255,0.7)" weight="regular" />
        </TouchableOpacity>
      </View>
    </View>
  );
}

function RevisionLista({ data, idx, onIr, onClose }) {
  const { formatYear, calendar } = useContext(SettingsContext);
  const [filtro, setFiltro] = useState('pend');
  const slideAnim = useRef(new Animated.Value(SH)).current;
  const opacAnim  = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.parallel([
      Animated.spring(slideAnim, { toValue:0, useNativeDriver:true, tension:60, friction:14 }),
      Animated.timing(opacAnim,  { toValue:1, duration:200, useNativeDriver:true }),
    ]).start();
  }, []);
  const close = () => {
    Animated.parallel([
      Animated.timing(slideAnim, { toValue:SH, duration:240, useNativeDriver:true }),
      Animated.timing(opacAnim,  { toValue:0,  duration:200, useNativeDriver:true }),
    ]).start(onClose);
  };
  const nombres = useMemo(() => { const m = {}; for (const c of CIVILIZATIONS) m[c.id] = c.etiqueta || c.name; return m; }, []);
  const filas = useMemo(() => REVISION_ORDEN.map((e, i) => ({ e, i, d: data[e[0]] }))
    .filter(r => filtro === 'todas' ? true : filtro === 'pend' ? !(r.d && r.d.v) : (r.d && r.d.v === filtro)), [filtro, data]);
  const cuenta = { todas: REVISION_ORDEN.length, pend: 0, bien: 0, mal: 0, duda: 0 };
  for (const e of REVISION_ORDEN) { const d = data[e[0]]; if (d && d.v) cuenta[d.v] = (cuenta[d.v] || 0) + 1; else cuenta.pend++; }
  const exportar = async () => {
    const salida = { fecha: new Date().toISOString(), total: REVISION_ORDEN.length, veredictos: data };
    try { await Share.share({ message: JSON.stringify(salida), title: 'Revisión BlueDot' }); } catch (_) {}
  };
  return (
    <Animated.View style={[mSt.overlay, { opacity: opacAnim }]} pointerEvents="box-none">
      <Pressable style={StyleSheet.absoluteFill} onPress={close} />
      <Animated.View style={[mSt.sheet, { transform:[{ translateY: slideAnim }], height: SH * 0.85 }]}>
        <View style={mSt.handle} />
        <View style={mSt.header}>
          <Text style={mSt.title}>Revisión del mapa</Text>
          <TouchableOpacity onPress={exportar} style={[mSt.closeBtn, { marginRight:10 }]}>
            <Export size={15} color="rgba(255,255,255,0.7)" weight="regular" />
          </TouchableOpacity>
          <Pressable onPress={close} style={mSt.closeBtn}><Text style={mSt.closeTxt}>✕</Text></Pressable>
        </View>
        <View style={[mSt.pillGroupH, { paddingHorizontal:24, paddingVertical:12 }]}>
          {[['pend','Pendientes'],['bien','Bien'],['mal','Mal'],['duda','No sé'],['todas','Todas']].map(([k, l]) => (
            <Pressable key={k} style={[mSt.pillH, { paddingHorizontal:12, paddingVertical:7 }, filtro===k && mSt.pillOn]} onPress={() => setFiltro(k)}>
              <Text style={[mSt.pillTxt, { fontSize:12 }, filtro===k && mSt.pillTxtOn]}>{l + ' ' + cuenta[k]}</Text>
            </Pressable>
          ))}
        </View>
        <FlatList
          data={filas}
          keyExtractor={r => r.e[0]}
          getItemLayout={(_, i) => ({ length: 48, offset: 48 * i, index: i })}
          initialNumToRender={20}
          renderItem={({ item: r }) => (
            <Pressable style={[revSt.filaLista, r.i === idx && revSt.filaListaOn]} onPress={() => { onIr(r.i); close(); }}>
              <View style={[revSt.punto, { backgroundColor: revColor(r.d && r.d.v) }]} />
              <View style={{ flex:1 }}>
                <Text style={revSt.listaNombre} numberOfLines={1}>{nombres[r.e[0]] || r.e[0]}</Text>
                <Text style={revSt.listaSub} numberOfLines={1}>
                  {(r.i + 1) + '  ·  ' + formatYear(r.e[2], calendar) + (r.e[5] ? '  ·  cultura' : '') + (r.d && r.d.n ? '  ·  ' + r.d.n : '')}
                </Text>
              </View>
            </Pressable>
          )}
        />
      </Animated.View>
    </Animated.View>
  );
}

function RevisionNota({ nombre, inicial, onGuardar, onClose }) {
  const [txt, setTxt] = useState(inicial || '');
  return (
    <View style={[mSt.overlay, { backgroundColor:'rgba(0,0,0,0.55)', justifyContent:'center' }]}>
      <Pressable style={StyleSheet.absoluteFill} onPress={onClose} />
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={{ marginHorizontal:24 }}>
        <View style={revSt.notaCaja}>
          <Text style={[mSt.sectionTitle, { marginBottom:10 }]} numberOfLines={1}>{nombre}</Text>
          <TextInput value={txt} onChangeText={setTxt} multiline autoFocus
            placeholder="Qué está mal, qué falta, qué sobra" placeholderTextColor="rgba(255,255,255,0.3)"
            style={revSt.notaInput} />
          <View style={{ flexDirection:'row', justifyContent:'flex-end', gap:10, marginTop:12 }}>
            <TouchableOpacity style={[mSt.actionBtn, { marginTop:0, backgroundColor:'rgba(255,255,255,0.06)', borderColor:'rgba(255,255,255,0.15)' }]} onPress={onClose}>
              <Text style={[mSt.actionBtnTxt, { color:'rgba(255,255,255,0.6)' }]}>Cancelar</Text>
            </TouchableOpacity>
            <TouchableOpacity style={[mSt.actionBtn, { marginTop:0 }]} onPress={() => onGuardar(txt.trim())}>
              <Text style={mSt.actionBtnTxt}>Guardar</Text>
            </TouchableOpacity>
          </View>
        </View>
      </KeyboardAvoidingView>
    </View>
  );
}

const revSt = StyleSheet.create({
  bar:        { position:'absolute', bottom:0, left:0, right:0, backgroundColor:'rgba(4,4,13,0.92)', borderTopWidth:0.5, borderColor:'rgba(255,255,255,0.08)', paddingTop:8, paddingBottom:28, paddingHorizontal:12, gap:8 },
  fila:       { flexDirection:'row', alignItems:'center', gap:8 },
  nombre:     { color:'#fff', fontSize:15, fontWeight:'600', letterSpacing:-0.2 },
  sub:        { color:'rgba(255,255,255,0.45)', fontSize:11, marginTop:2 },
  btnSec:     { width:38, height:38, borderRadius:19, backgroundColor:'rgba(255,255,255,0.07)', borderWidth:0.5, borderColor:'rgba(255,255,255,0.15)', alignItems:'center', justifyContent:'center' },
  btnSecOn:   { backgroundColor:'rgba(55,138,221,0.18)', borderColor:'rgba(55,138,221,0.55)' },
  btnVer:     { flex:1, height:38, borderRadius:19, borderWidth:0.5, flexDirection:'row', alignItems:'center', justifyContent:'center', gap:5 },
  btnVerTxt:  { fontSize:12, fontWeight:'600' },
  filaLista:  { height:48, flexDirection:'row', alignItems:'center', gap:12, paddingHorizontal:24, borderBottomWidth:0.5, borderColor:'rgba(255,255,255,0.05)' },
  filaListaOn:{ backgroundColor:'rgba(55,138,221,0.12)' },
  punto:      { width:9, height:9, borderRadius:4.5 },
  listaNombre:{ color:'rgba(255,255,255,0.88)', fontSize:13, fontWeight:'500' },
  listaSub:   { color:'rgba(255,255,255,0.38)', fontSize:11, marginTop:1 },
  notaCaja:   { backgroundColor:'#0c0c1c', borderRadius:18, borderWidth:0.5, borderColor:'rgba(255,255,255,0.1)', padding:18 },
  notaInput:  { minHeight:90, color:'#fff', fontSize:14, lineHeight:20, backgroundColor:'rgba(255,255,255,0.05)', borderRadius:12, padding:12, textAlignVertical:'top' },
});

// ─── Main App Component ───────────────────────────────────────────────────────
// Single component with two WebViews. Globe is always mounted (opacity 0 when hidden).
// Orbital sends {type:'showGlobe'} → we fade globe in, fade orbital out.
// Pinch-out on globe sends {type:'zoomOutExit'} → we reverse.

export default function BlueDotApp() {
  const storeYear    = useTimeStore(s => s.currentYear);
  const setStoreYear = useTimeStore(s => s.setYear);

  // Consume settings — drives colors, font sizes, contrast across whole app
  const { fontSize, daltonism, contrast, calendar, palette, bgColor } = useContext(SettingsContext);
  const paletteRef = useRef(palette);
  useEffect(() => { paletteRef.current = palette; }, [palette]);

  // Re-send pins with new colors when daltonism toggles
  useEffect(() => {
    sendPins(yearRef.current, activeCatRef.current, toleranceRef.current, true);
  }, [daltonism]);

  // Which view is active: 'orbital' | 'globe'
  const [screen, setScreen] = useState('orbital');
  const screenRef = useRef('orbital'); // ref version for use in callbacks/intervals
  const orbitalOpacity = useRef(new Animated.Value(1)).current;
  const globeOpacity   = useRef(new Animated.Value(0)).current;

  const orbitalRef = useRef(null);
  const globeRef   = useRef(null);

  // ── Globe state (was ExploreScreen state) ─────────────────────────────────
// ─── Globe section state/logic (embedded in BlueDotApp) ─────────────────────

  const [year,            setYear]           = useState(storeYear);
  const [tolerance,       setTolerance]      = useState(5);
  // Eventos apagados y civilizaciones encendidas por defecto al abrir la app.
  const [activeCategories,setActiveCategories] = useState([]);
  const [processLayers,   setProcessLayers]  = useState({
    civilizations:true, routes:false, wars:false,
    migration:false, religion:false, languages:false,
    showCivilNames:true,
    // Las areas culturales (kind:'cultura') se pueden apagar por separado:
    // son 299 de las 873 entidades y dominan visualmente los milenios
    // anteriores a los primeros estados.
    showCultures:true,
  });
  const [processItemsOn,  setProcessItemsOn] = useState({
    civilizations:{}, routes:{}, wars:{}, migration:{}, religion:{}, languages:{},
  });
  const [showDrawer,    setShowDrawer]    = useState(false);
  // Persistent user preference (drawer toggle) for the globe's idle
  // auto-spin -- independent of the transient lockRotation/unlockRotation
  // messages sent while a card is open, which only pause it temporarily.
  const [autoRotate, setAutoRotate] = useState(true);
  const autoRotateRef = useRef(true);
  useEffect(() => { autoRotateRef.current = autoRotate; }, [autoRotate]);
  // Mapa 2D (proyección equirectangular) vs globo 3D — toggle del menú
  const [flatMap, setFlatMap] = useState(false);
  const flatMapRef = useRef(false);
  useEffect(() => { flatMapRef.current = flatMap; }, [flatMap]);
  const [showSearch,    setShowSearch]    = useState(false);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [routeCard,     setRouteCard]     = useState(null);
  const [riverCard,     setRiverCard]     = useState(null);
  const [wonderCard,    setWonderCard]    = useState(null);
  const [migrationCard, setMigrationCard] = useState(null);
  const [languageCard,  setLanguageCard]  = useState(null);
  const [religionCard,  setReligionCard]  = useState(null);
  const [civilizationCard, setCivilizationCard] = useState(null);
  const [warCard, setWarCard] = useState(null);
  const [showChat, setShowChat] = useState(false);
  const [chatSeed, setChatSeed] = useState(null);
  // Lifted out of AIChatPanel (which unmounts every time the chat closes,
  // e.g. from the navigateFromAI auto-close above) so the conversation
  // survives close/reopen instead of resetting to empty each time.
  const [chatMessages, setChatMessages] = useState([]);

  const [divisionLayers, setDivisionLayers] = useState({
    countries: false, countries_names: false,
    tectonic: false,  tectonic_names: false,
    geolines: false,  geolines_names: false,
    mountains: false, mountains_names: false,
    rivers: false,    rivers_names: false, lakes: false,
    deserts: false,   deserts_names: false,
    wonders: false,   wonders_names: false,
  });
  const divisionLayersRef = useRef({
    countries: false, countries_names: false,
    tectonic: false,  tectonic_names: false,
    geolines: false,  geolines_names: false,
    mountains: false, mountains_names: false,
    rivers: false,    rivers_names: false, lakes: false,
    deserts: false,   deserts_names: false,
    wonders: false,   wonders_names: false,
  });
  useEffect(() => { divisionLayersRef.current = divisionLayers; }, [divisionLayers]);

  const sendDivisions = useCallback((layers) => {
    if (!globeRef.current) return;
    globeRef.current.postMessage(JSON.stringify({ type:'updateDivisions', layers }));
  }, []);

  const toggleDivision = useCallback((id) => {
    setDivisionLayers(prev => {
      const next = { ...prev, [id]: !prev[id] };
      // Kept in sync synchronously (not just via the useEffect above) so
      // sendProcesses -- called a few lines down for wonders -- reads the
      // fresh value immediately instead of racing the effect.
      divisionLayersRef.current = next;
      setTimeout(() => {
        sendDivisions(next);
        // "Maravillas del mundo" lives in this Divisiones list, but its
        // glyphs are year-filtered and actually ride on the processes pipe
        // (see sendProcesses) rather than the static divisions one -- so
        // toggling it needs a forced processes refresh too, or the glyphs
        // wouldn't show/hide until the next unrelated year-driven update.
        if (id === 'wonders' || id === 'wonders_names') {
          sendProcesses(yearRef.current, processLayersRef.current, processItemsOnRef.current, true);
        }
      }, 0);
      return next;
    });
  }, [sendDivisions, sendProcesses]);

  const sendAutoRotate = useCallback((enabled) => {
    globeRef.current?.postMessage(JSON.stringify({ type:'setAutoRotate', enabled }));
  }, []);

  const toggleAutoRotate = useCallback(() => {
    setAutoRotate(prev => {
      const next = !prev;
      setTimeout(() => sendAutoRotate(next), 0);
      return next;
    });
  }, [sendAutoRotate]);

  const toggleFlatMap = useCallback(() => {
    setFlatMap(prev => {
      const next = !prev;
      globeRef.current?.postMessage(JSON.stringify({ type:'setMapMode', flat: next }));
      return next;
    });
  }, []);

  // Playback
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed,     setSpeed]     = useState(1);

  // webviewRef renamed to globeRef (declared in BlueDotApp)
  const yearRef        = useRef(storeYear);
  const speedRef       = useRef(1);
  // Sentido de la reproducción: +1 hacia el futuro, -1 hacia el pasado.
  const [playDir, setPlayDir] = useState(1);
  const playDirRef     = useRef(1);
  const lastPinsSentRef = useRef(-99999);
  const lastProcSentRef = useRef(-99999);
  const ultimaFirmaRef  = useRef('');
  // Claves de territorio+periodo cuya geometria ya viaja en el motor del
  // globo: no hace falta volver a serializar sus coordenadas.
  const enviadasRef     = useRef(new Set());
  const processLayersRef  = useRef(processLayers);
  const processItemsOnRef = useRef(processItemsOn);
  const activeCatRef      = useRef(activeCategories);
  const toleranceRef      = useRef(tolerance);

  useEffect(() => { speedRef.current = speed; }, [speed]);
  useEffect(() => { playDirRef.current = playDir; }, [playDir]);
  useEffect(() => { processLayersRef.current = processLayers; }, [processLayers]);
  useEffect(() => { processItemsOnRef.current = processItemsOn; }, [processItemsOn]);
  useEffect(() => { activeCatRef.current = activeCategories; }, [activeCategories]);
  useEffect(() => { toleranceRef.current = tolerance; }, [tolerance]);

  // ── Derived process data ─────────────────────────────────────────────────
  // Se memoiza por año: durante la reproducción este componente se vuelve a
  // pintar 20 veces por segundo, y recorrer las 648 civilizaciones (más rutas,
  // guerras, migraciones, religiones y lenguas) en cada pintado era una de
  // las causas del tirón. Con useMemo solo se recalcula cuando el año cambia
  // de verdad.
  const roundedYear     = Math.round(year);
  const narrative       = useMemo(() => getNarrative(roundedYear),       [roundedYear]);
  const activeCivils    = useMemo(() => getActiveCivils(roundedYear),    [roundedYear]);
  const activeRoutes    = useMemo(() => getActiveRoutes(roundedYear),    [roundedYear]);
  const activeWars      = useMemo(() => getActiveWars(roundedYear),      [roundedYear]);
  const activeMigrations = useMemo(() => getActiveMigrations(roundedYear), [roundedYear]);
  const activeReligions  = useMemo(() => getActiveReligions(roundedYear),  [roundedYear]);
  const activeLanguages  = useMemo(() => getActiveLanguages(roundedYear),  [roundedYear]);

  // Respeta los toggles individuales (processItemsOn) además del toggle de
  // capa entera -- antes de este fix la tira de "chips" de abajo no los
  // tenía en cuenta e incluía civs/rutas/guerras apagadas una por una.
  const itemIsOn = (pid, id) => (processItemsOn[pid] || {})[id] !== false;

  // `type`+`data` (el objeto completo, no solo id/name/color) permiten que
  // cada chip abra su ficha al tocarlo -- ver el onPress más abajo, que
  // reutiliza openProcessCard (la misma función que ya usa el buscador).
  const activeItems = useMemo(() => [
    ...(processLayers.civilizations ? activeCivils.filter(c=>(processLayers.showCultures!==false||c.kind!=='cultura')&&itemIsOn('civilizations',c.id)).map(c=>({id:c.id,name:c.baseName,color:c.color,type:'civilizations',data:c})) : []),
    ...(processLayers.routes     ? activeRoutes.filter(r=>itemIsOn('routes',r.id)).map(r=>({id:r.id,name:r.name,color:r.color,type:'routes',data:r})) : []),
    ...(processLayers.wars       ? activeWars.filter(w=>itemIsOn('wars',w.id)).map(w=>({id:w.id,name:w.name,color:w.color,type:'wars',data:w})) : []),
    ...(processLayers.migration  ? activeMigrations.filter(m=>itemIsOn('migration',m.id)).map(m=>({id:m.id,name:m.name,color:m.color,type:'migration',data:m})) : []),
    ...(processLayers.religion   ? activeReligions.filter(r=>itemIsOn('religion',r.id)).map(r=>({id:r.id,name:r.name,color:r.color,type:'religion',data:r})) : []),
    ...(processLayers.languages  ? activeLanguages.filter(l=>itemIsOn('languages',l.id)).map(l=>({id:l.id,name:l.name,color:l.color,type:'languages',data:l})) : []),
  ], [activeCivils, activeRoutes, activeWars, activeMigrations, activeReligions, activeLanguages, processLayers, processItemsOn]);

  // ── Send pins to WebView ─────────────────────────────────────────────────
  const sendPins = useCallback((yr, cats, tol, force = false) => {
    if (!globeRef.current) return;
    const rounded = Math.round(yr);
    Paquetes.asegurar(rounded, tol);
    if (!force && Math.abs(rounded - lastPinsSentRef.current) < 2) return;
    lastPinsSentRef.current = rounded;
    const pinsJson = makeEventsJSON(rounded, cats, tol, paletteRef.current);
    globeRef.current.postMessage(JSON.stringify({ type:'updatePins', pins: JSON.parse(pinsJson) }));
  }, []);

  // ── Send process layers to WebView ───────────────────────────────────────
  const sendProcesses = useCallback((yr, layers, itemsOn, force = false) => {
    if (!globeRef.current) return;
    const rounded = Math.round(yr);
    if (!force && Math.abs(rounded - lastProcSentRef.current) < 3) return;
    lastProcSentRef.current = rounded;

    const curItemsOn = itemsOn || processItemsOnRef.current;
    // La clave `k` identifica territorio + periodo: con ella el motor
    // del globo guarda la malla ya triangulada y evita rehacerla.
    const verCulturas = layers.showCultures !== false;
    const civils = getActiveCivils(rounded)
      .filter(c => verCulturas || c.kind !== 'cultura')
      .filter(c => (curItemsOn.civilizations||{})[c.id] !== false)
      .map(c => {
        const k = c.id+'@'+c.periodStart;
        // EL ROTULO DEL GLOBO NO ES EL NOMBRE DE LA FICHA.
        //
        // El nombre de una entidad hace dos trabajos con longitudes contrarias.
        // En la ficha conviene que diga de que se trata: "Cazadores y campesinos
        // del bosque templado de Europa central y occidental" informa. Encima
        // del territorio ese mismo texto es una franja de setenta y tres
        // caracteres cruzando media Europa.
        //
        // Ciento sesenta y nueve entidades pasan de veintiocho caracteres y
        // ciento veintinueve de ellas son areas culturales, que es donde el
        // nombre se volvio descripcion. Esas llevan ahora un campo etiqueta con
        // el rotulo corto. La ficha y la leyenda siguen usando el nombre largo,
        // que es donde hay sitio para leerlo.
        const base = { id:c.id, k, color:c.color, opacity:c.opacity, inc:c.inc, cult:c.kind==='cultura'?1:0, name:c.etiqueta || c.baseName };
        // Las coordenadas solo viajan la primera vez que se ve el territorio;
        // despues basta la clave, porque el motor ya tiene la malla montada.
        return (force || !enviadasRef.current.has(k)) ? { ...base, rings:c.rings } : base;
      });
    const routes = getActiveRoutes(rounded)
      .filter(r => (curItemsOn.routes||{})[r.id] !== false)
      .map(r => ({ id:r.id, color:r.color, points:r.points }));
    const wars = getActiveWars(rounded)
      .filter(w => (curItemsOn.wars||{})[w.id] !== false)
      .map(w => ({ id:w.id, color:w.color, lat:w.lat, lon:w.lon, radius:w.radius, battles:w.battles || [] }));
    const migration = getActiveMigrations(rounded)
      .map(m => ({ id:m.id, color:m.color, type:m.type, waypoints:m.waypoints, name:m.name }));
    const religion = getActiveReligions(rounded)
      .map(r => ({ id:r.id, color:r.color, rings:r.rings, name:r.name, wikiTitle:r.wikiTitle }));
    const languages = getActiveLanguages(rounded)
      .map(l => ({ id:l.id, color:l.color, rings:l.rings, name:l.name, wikiTitle:l.wikiTitle }));
    // Wonders' on/off toggle lives in the Divisiones drawer section (not
    // `layers`, which is processLayers), but the actual glyphs still need to
    // be filtered by the current year -- so the data rides along on this
    // same year-aware message instead of the static 'updateDivisions' one.
    const wondersOn = divisionLayersRef.current.wonders;
    const wonders = wondersOn ? getActiveWonders(rounded).map(w => ({ id:w.id, name:w.name, lat:w.lat, lon:w.lon, type:w.type, shape:w.shape, pts:w.pts })) : [];

    // Nada de esto cambia cada año: el mapa solo se mueve de verdad en el
    // 15% de los años del eje. Si el conjunto de territorios, rutas, guerras,
    // migraciones, religiones, lenguas y maravillas es el mismo que el del
    // último envío, no se manda el mensaje -- serializar medio megabyte de
    // coordenadas y retriangularlo para pintar exactamente lo mismo era lo
    // que atascaba la reproducción.
    const firma = civils.map(c=>c.k).join(',')+'#'+routes.map(r=>r.id).join(',')
      +'#'+wars.map(w=>w.id).join(',')+'#'+migration.map(m=>m.id).join(',')
      +'#'+religion.map(r=>r.id).join(',')+'#'+languages.map(l=>l.id).join(',')
      +'#'+wonders.map(w=>w.id).join(',')+'#'+(wondersOn?1:0)
      +'#'+(divisionLayersRef.current.wonders_names?1:0)+'#'+JSON.stringify(layers);
    if (!force && firma === ultimaFirmaRef.current) return;
    ultimaFirmaRef.current = firma;

    // Un envio forzado rehace el mapa desde cero, asi que tambien vacia el
    // cache del motor: los dos lados vuelven a partir del mismo estado.
    if (force) enviadasRef.current = new Set();
    globeRef.current.postMessage(JSON.stringify({
      type:'updateProcesses', layers, civils, routes, wars, migration, religion, languages, baseOn: layers.showCultures !== false,
      wonders, wondersOn, wondersNamesOn: divisionLayersRef.current.wonders_names,
      purgar: force || undefined,
    }));
    for (const c of civils) enviadasRef.current.add(c.k);
  }, []);

  // Repinta el globo AHORA, saltándose el estrangulador de años. Se usa al
  // arrancar/parar el play y al cambiar de sentido: sin esto, invertir la
  // dirección puede tardar hasta 3 años de simulación (varios segundos a
  // velocidad baja) en verse, y parece que "no funciona".
  const forzarRepintado = useCallback(() => {
    lastPinsSentRef.current = -99999;
    lastProcSentRef.current = -99999;
    sendPins(yearRef.current, activeCatRef.current, toleranceRef.current, true);
    sendProcesses(yearRef.current, processLayersRef.current, processItemsOnRef.current, true);
  }, [sendPins, sendProcesses]);

  // Paquetes: al arrancar lee qué eras hay instaladas; cada vez que una era
  // entra o sale de memoria, el globo se repinta con los eventos que toca.
  useEffect(() => {
    const off = Paquetes.suscribir(() => {
      lastPinsSentRef.current = -99999;
      sendPins(yearRef.current, activeCatRef.current, toleranceRef.current, true);
    });
    Paquetes.iniciar();
    return off;
  }, []); // eslint-disable-line

  const lastStoreSyncRef = useRef(0);
  const playIntervalRef = useRef(null);

  // ── Play loop: plain setInterval, no RAF, no re-render issues ────────────
  // Called every 50ms (~20fps). Advances year using refs only.
  // setYear called in the same interval to update UI — no separate effect needed.
  useEffect(() => {
    if (isPlaying) {
      playIntervalRef.current = setInterval(() => {
        const dt = 0.05; // 50ms in seconds
        // El paso lleva el signo de playDirRef, así que la misma línea sirve
        // para avanzar y para retroceder; los topes se aplican a los dos lados.
        const paso = playDirRef.current * speedRef.current * 5 * dt;
        const newY = Math.max(ANIO_MIN, Math.min(2025, yearRef.current + paso));
        yearRef.current = newY;
        const rounded = Math.round(newY);

        // Update UI year wheel
        setYear(rounded);

        // Sync store every 500ms
        if (Date.now() - lastStoreSyncRef.current > 500) {
          setStoreYear(rounded);
          lastStoreSyncRef.current = Date.now();
          // Also push year to orbital canvas so it stays in sync
          orbitalRef.current?.postMessage(JSON.stringify({ type:'setYear', year: rounded }));
        }

        // Send to globe WebView
        sendPins(newY, activeCatRef.current, toleranceRef.current, false);
        sendProcesses(newY, processLayersRef.current, processItemsOnRef.current, false);

        // Stop at either end
        if (newY >= 2025 || newY <= ANIO_MIN) {
          setIsPlaying(false);
        }
      }, 50);
    } else {
      if (playIntervalRef.current) {
        clearInterval(playIntervalRef.current);
        playIntervalRef.current = null;
      }
      setYear(Math.round(yearRef.current));
      setStoreYear(Math.round(yearRef.current));
    }
    return () => {
      if (playIntervalRef.current) {
        clearInterval(playIntervalRef.current);
        playIntervalRef.current = null;
      }
    };
  }, [isPlaying]); // eslint-disable-line

  // ── Re-send when layers/tolerance change ─────────────────────────────────
  useEffect(() => {
    sendPins(yearRef.current, activeCategories, tolerance, true);
  }, [activeCategories, tolerance]);

  useEffect(() => {
    sendProcesses(yearRef.current, processLayers, processItemsOn, true);
  }, [processLayers, processItemsOn]);

  // Eventos para la vista orbital, una sola vez. Los puntos sobre la órbita son
  // los de importancia 5; el rótulo bajo el año usa también los de 3 y 4, para
  // que un año con algo que contar (2000: Fox, fin del PRI) no muestre el
  // suceso del año de al lado (2001: 11-S) como si fuera suyo.
  const orbitalEvents = EVENTS
    .filter(e => (e.importance||3) >= 3 && !e.fondo)
    .map(e => ({
      y: e.year,
      i: e.importance || 3,
      l: e.labels?.es || e.labels?.en || e.label || '',
      c: CATEGORY_COLORS_NORMAL[e.category] || '#D85A30',
    }));

  const onWebViewLoad = useCallback(() => {
    setTimeout(() => {
      sendPins(yearRef.current, activeCatRef.current, toleranceRef.current, true);
      sendProcesses(yearRef.current, processLayersRef.current, processItemsOnRef.current, true);
      sendDivisions(divisionLayersRef.current);
      sendAutoRotate(autoRotateRef.current);
      globeRef.current?.postMessage(JSON.stringify({ type:'revLoad' }));
      globeRef.current?.postMessage(JSON.stringify({ type:'baseTierra', rings:TIERRA_BASE }));
      // Reaplicar el modo mapa 2D si estaba activo (el WebView arranca en globo)
      if (flatMapRef.current) {
        globeRef.current?.postMessage(JSON.stringify({ type:'setMapMode', flat:true }));
      }
    }, 500);
  }, [sendPins, sendProcesses, sendDivisions, sendAutoRotate]);

  const onOrbitalLoad = useCallback(() => {
    setTimeout(() => {
      orbitalRef.current?.postMessage(JSON.stringify({
        type: 'updateOrbitalEvents',
        events: orbitalEvents,
      }));
    }, 300);
  }, []);

  // ── Camera rotation to event ──────────────────────────────────────────────
  const rotateToEvent = useCallback((ev) => {
    if (!globeRef.current) return;
    globeRef.current.postMessage(JSON.stringify({ type:'rotateTo', lat:ev.lat, lon:ev.lon }));
  }, []);

  // Track whether play was active before opening a card so we can restore it
  const wasPlayingRef = useRef(false);

  const openEvent = useCallback((ev) => {
    // 1. Pause playback
    wasPlayingRef.current = isPlaying;
    setIsPlaying(false);
    // 2. Lock globe inertia and auto-spin
    globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
    // 3. Rotate to location
    setTimeout(() => rotateToEvent(ev), 80);
    // 4. Show card
    setTimeout(() => setSelectedEvent(ev), 180);
  }, [isPlaying, rotateToEvent]);

  const closeEvent = useCallback((opts) => {
    setSelectedEvent(null);
    globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
    if (opts?.navigateTo) {
      const target = EVENTS.find(ev => ev.id === opts.navigateTo.id);
      if (target) {
        // Sync year to the target event before opening its card
        const targetYear = target.year;
        yearRef.current = targetYear;
        setYear(targetYear);
        setStoreYear(targetYear);
        sendPins(targetYear, activeCatRef.current, toleranceRef.current, true);
        setTimeout(() => openEvent(target), 120);
        return;
      }
    }
    if (wasPlayingRef.current) setIsPlaying(true);
  }, [openEvent, setStoreYear, sendPins]);

  // Abre la ficha de una civilización/religión/idioma/guerra/ruta/migración
  // elegida desde el buscador -- mismo efecto (pausa, bloquea rotación,
  // muestra ficha) que tocarla directo en el globo (ver los handlers
  // 'civilizationTap'/'religionTap'/etc. en onGlobeMsg más abajo).
  const openProcessCard = useCallback((resultType, item) => {
    wasPlayingRef.current = isPlaying;
    setIsPlaying(false);
    globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
    if (resultType === 'civilizations') {
      const yr = Math.round(yearRef.current);
      const period = periodoEn(item.periods, yr);
      setCivilizationCard({ ...item, periodStart: period?.start, periodEnd: period?.end, periodWikiTitle: period?.wikiTitle, periodName: period?.name });
    } else if (resultType === 'religion') {
      setReligionCard(item);
    } else if (resultType === 'languages') {
      setLanguageCard(item);
    } else if (resultType === 'wars') {
      setWarCard({ ...item, focusBattleIdx: null });
    } else if (resultType === 'routes') {
      setRouteCard(item);
    } else if (resultType === 'migration') {
      setMigrationCard(item);
    }
  }, [isPlaying]);

  // Pure lookup, no side effects -- lets the chat preview what a
  // navigate_map action points to (e.g. to show the entity's name on a
  // tappable suggestion chip) without actually jumping anywhere. See
  // navigateFromAI below for the version that acts on it.
  const resolveNavTarget = useCallback((resultType, entityId) => {
    return resultType && entityId
      ? SEARCH_COLLECTIONS.find(c => c.resultType === resultType)?.items.find(it => it.id === entityId)
      : null;
  }, []);

  // AI-driven navigation -- the same "jump year (+ turn the layer/item on
  // if needed) + open the card" effect as picking a result from the
  // search modal (see onSelectProcess below), except the year and
  // entity are decided by the assistant's navigate_map tool call instead
  // of a tap. resultType/entityId come straight from SEARCH_COLLECTIONS'
  // vocabulary, which is also what buildStructuredContext() uses, so no
  // translation is needed between "what the AI said" and "what the app
  // understands". Unlike resolveNavTarget above, this one actually acts --
  // it's only called when the person taps the suggestion chip in chat,
  // never automatically just because the model called the tool (see
  // AIChatPanel: navigate_map results in a tappable suggestion, not an
  // immediate jump -- the person decides whether to go or keep chatting).
  const navigateFromAI = useCallback((year, resultType, entityId) => {
    const jumpYear = year != null ? year : yearRef.current;
    yearRef.current = jumpYear; setYear(jumpYear); setStoreYear(jumpYear);

    const item = resolveNavTarget(resultType, entityId);

    if (item) {
      const nextLayers = { ...processLayersRef.current, [resultType]: true };
      const nextItemsOn = {
        ...processItemsOnRef.current,
        [resultType]: { ...(processItemsOnRef.current[resultType] || {}), [item.id]: true },
      };
      setProcessLayers(nextLayers);
      setProcessItemsOn(nextItemsOn);
      sendPins(jumpYear, activeCatRef.current, toleranceRef.current, true);
      sendProcesses(jumpYear, nextLayers, nextItemsOn, true);
      // Close the chat so the card that's about to open is actually visible
      // instead of stacking underneath/behind the still-open chat panel --
      // the conversation itself isn't lost (messages live in the parent,
      // not inside AIChatPanel, so it's exactly where it was if the person
      // reopens the chat afterward, "jumped to X" confirmation included).
      setShowChat(false);
      setTimeout(() => openProcessCard(resultType, item), 120);
    } else {
      sendPins(jumpYear, activeCatRef.current, toleranceRef.current, true);
      sendProcesses(jumpYear, processLayersRef.current, processItemsOnRef.current, true);
    }
    return item; // let the caller show a confirmation chip with item.name
  }, [resolveNavTarget, openProcessCard, sendPins, sendProcesses]);

  // Opens the AI chat -- used both by the "Ask AI" row inside the search
  // modal and by the "Ask AI about this" button every info card carries,
  // so someone reading a card can go deeper without retyping who/what
  // they're asking about. Closes whichever card is currently open first
  // (only one is ever open at a time, so unconditionally clearing all of
  // them is simplest and safe).
  //
  // Accepts three shapes:
  //  - a string: auto-sends it immediately (the search modal's "Ask AI:
  //    <query>" row -- the person already typed a specific question).
  //  - an array: opens the chat with these as tappable quick-question
  //    chips instead of auto-sending any single one of them (every card's
  //    "Ask AI about this" button). A single hardcoded question felt
  //    repetitive across cards, and the model can't guess which angle
  //    (causes? outcome? related figures?) someone actually wants -- a
  //    few tailored options plus the open input let them pick or type
  //    their own.
  //  - null/undefined: opens a blank chat (search modal with no query).
  const askAIAbout = useCallback((input) => {
    setSelectedEvent(null);
    setRouteCard(null);
    setRiverCard(null);
    setWonderCard(null);
    setMigrationCard(null);
    setLanguageCard(null);
    setReligionCard(null);
    setCivilizationCard(null);
    setWarCard(null);
    globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
    if (Array.isArray(input)) {
      setChatSeed({ question: null, autoSend: false, suggestions: input });
    } else {
      setChatSeed(input ? { question: input, autoSend: true } : null);
    }
    setShowChat(true);
  }, []);

  // ── Drawer toggles ────────────────────────────────────────────────────────
  const toggleCategory = useCallback((cat) => {
    setActiveCategories(prev =>
      prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
    );
  }, []);

  // Botón "Apagar todos" / "Encender todos" del drawer -- si hay al menos
  // una categoría de evento activa, las apaga todas de un golpe; si ya
  // están todas apagadas, restaura el set completo (mismo default con el
  // que arranca activeCategories) en vez de solo un subconjunto arbitrario.
  const toggleAllEvents = useCallback(() => {
    setActiveCategories(prev => (prev.length > 0 ? [] : Object.keys(CATEGORY_META)));
  }, []);

  const toggleProcess = useCallback((pid) => {
    setProcessLayers(prev => ({ ...prev, [pid]: !prev[pid] }));
  }, []);

  // Nombres de civilizaciones flotando sobre el territorio en el globo --
  // vive dentro de processLayers (en vez de un useState aparte) para que
  // el useEffect que ya re-envía 'updateProcesses' en cada cambio de
  // processLayers dispare la actualización sin código nuevo.
  const toggleCivilNames = useCallback(() => {
    setProcessLayers(prev => ({ ...prev, showCivilNames: prev.showCivilNames === false ? true : false }));
  }, []);

  // Encender/apagar las areas culturales. Vive tambien en processLayers para
  // que el useEffect que reenvia 'updateProcesses' lo propague solo, pero
  // ademas fuerza el reenvio porque el conjunto de territorios cambia.
  const toggleCultures = useCallback(() => {
    setProcessLayers(prev => ({ ...prev, showCultures: prev.showCultures === false ? true : false }));
  }, []);

  const toggleProcessItem = useCallback((pid, itemId) => {
    setProcessItemsOn(prev => ({
      ...prev,
      [pid]: { ...(prev[pid]||{}), [itemId]: (prev[pid]||{})[itemId] === false ? true : false },
    }));
  }, []);


  // zoom-out handled by switchToOrbital in BlueDotApp

  // ── Screen switch ─────────────────────────────────────────────────────────
  const switchToGlobe = useCallback(() => {
    screenRef.current = 'globe';
    setScreen('globe');
    // Sync orbital canvas to current year immediately so it's correct when user returns
    orbitalRef.current?.postMessage(JSON.stringify({ type:'setYear', year: Math.round(yearRef.current) }));
    Animated.parallel([
      Animated.timing(orbitalOpacity, { toValue:0, duration:0, useNativeDriver:true }),
      Animated.timing(globeOpacity,   { toValue:1, duration:0, useNativeDriver:true }),
    ]).start();
  }, []);

  const switchToOrbital = useCallback((yr) => {
    screenRef.current = 'orbital';
    const finalYear = yr ?? Math.round(yearRef.current);
    // Sync React state immediately — no waiting for orbital frame messages
    yearRef.current = finalYear;
    setYear(finalYear);
    setStoreYear(finalYear);
    setScreen('orbital');
    // Fade suave de globo a orbital — el canvas orbital ya está animando zoom-out
    Animated.sequence([
      Animated.timing(globeOpacity,   { toValue:0, duration:400, useNativeDriver:true }),
      Animated.timing(orbitalOpacity, { toValue:1, duration:300, useNativeDriver:true }),
    ]).start();
    // Tell orbital canvas: jump to year + play zoom-out animation (no setTimeout needed)
    orbitalRef.current?.postMessage(JSON.stringify({ type:'startZoomOut', year: finalYear }));
  }, [setStoreYear]);

  // ── Orbital messages ──────────────────────────────────────────────────────
  const [showOrbSettings, setShowOrbSettings] = useState(false);
  const [showOrbInfo,     setShowOrbInfo]     = useState(false);
  const [showYearEditor,  setShowYearEditor]  = useState(false);
  const [editorYear,      setEditorYear]      = useState(2000);

  const onOrbitalMsg = useCallback((e) => {
    try {
      const msg = JSON.parse(e.nativeEvent.data);
      if (msg.type === 'frame') {
        // Use screenRef (not screen state) — the closure captures the ref, always current
        if (screenRef.current === 'orbital') {
          yearRef.current = msg.year;
          setStoreYear(msg.year);
        }
        // When globe is active: orbital frame messages are ignored.
        // The play interval owns yearRef and advances it independently.
      } else if (msg.type === 'showGlobe') {
        // Orbital canvas sends its current year with showGlobe — sync it
        if (msg.year !== undefined) {
          yearRef.current = msg.year;
          setYear(msg.year);
          setStoreYear(msg.year);
        }
        sendPins(yearRef.current, activeCatRef.current, toleranceRef.current, true);
        sendProcesses(yearRef.current, processLayersRef.current, processItemsOnRef.current, true);
        switchToGlobe();
      } else if (msg.type === 'doubleTapYear') {
        setEditorYear(msg.year);
        setShowYearEditor(true);
      }
    } catch (_) {}
  }, [setStoreYear, switchToGlobe, sendPins, sendProcesses]);

  const handleYearEditorConfirm = useCallback((yr) => {
    orbitalRef.current?.postMessage(JSON.stringify({ type:'setYear', year:yr }));
    setStoreYear(yr);
  }, [setStoreYear]);

  // ── Modo revisión ──────────────────────────────────────────────────────────
  const [revOn,      setRevOn]      = useState(false);
  const [revIdx,     setRevIdx]     = useState(0);
  const [revData,    setRevData]    = useState({});
  const [revAislar,  setRevAislar]  = useState(false);
  const [showRevLista, setShowRevLista] = useState(false);
  const [revNotaDe,  setRevNotaDe]  = useState(null);
  const revDataRef = useRef({});
  const revTodosOff = useMemo(() => { const o = {}; for (const c of CIVILIZATIONS) o[c.id] = false; return o; }, []);
  const revGuardar = useCallback((next) => {
    revDataRef.current = next; setRevData(next);
    globeRef.current?.postMessage(JSON.stringify({ type:'revSave', data: JSON.stringify(next) }));
  }, []);
  const revIr = useCallback((idx, aislar) => {
    const n = REVISION_ORDEN.length; idx = ((idx % n) + n) % n;
    const e = REVISION_ORDEN[idx];
    const y = e[2];
    setIsPlaying(false);
    yearRef.current = y; setYear(y); setStoreYear(y);
    const nextLayers = { ...processLayersRef.current, civilizations:true, showCultures:true };
    const civOn = aislar ? { ...revTodosOff, [e[0]]: true } : { ...(processItemsOnRef.current.civilizations || {}), [e[0]]: true };
    const nextItemsOn = { ...processItemsOnRef.current, civilizations: civOn };
    setProcessLayers(nextLayers); setProcessItemsOn(nextItemsOn);
    processLayersRef.current = nextLayers; processItemsOnRef.current = nextItemsOn;
    sendPins(y, activeCatRef.current, toleranceRef.current, true);
    sendProcesses(y, nextLayers, nextItemsOn, true);
    globeRef.current?.postMessage(JSON.stringify({ type:'rotateTo', lat:e[3], lon:e[4] }));
    setRevIdx(idx);
  }, [sendPins, sendProcesses, revTodosOff]);
  const revSiguientePendiente = useCallback((desde) => {
    const n = REVISION_ORDEN.length;
    for (let k = 1; k <= n; k++) { const j = (desde + k) % n; const d = revDataRef.current[REVISION_ORDEN[j][0]]; if (!(d && d.v)) return j; }
    return (desde + 1) % n;
  }, []);
  const revEntrar = useCallback(() => {
    if (screenRef.current !== 'globe') switchToGlobe();
    setRevOn(true); setRevAislar(false);
    globeRef.current?.postMessage(JSON.stringify({ type:'revLoad' }));
    setTimeout(() => revIr(revSiguientePendiente(-1), false), 150);
  }, [switchToGlobe, revIr, revSiguientePendiente]);
  const revSalir = useCallback(() => {
    setRevOn(false); setShowRevLista(false); setRevNotaDe(null);
    if (revAislar) {
      const nextItemsOn = { ...processItemsOnRef.current, civilizations: {} };
      setProcessItemsOn(nextItemsOn); processItemsOnRef.current = nextItemsOn;
      sendProcesses(yearRef.current, processLayersRef.current, nextItemsOn, true);
    }
    setRevAislar(false);
  }, [revAislar, sendProcesses]);
  const revVeredicto = useCallback((v) => {
    const id = REVISION_ORDEN[revIdx][0];
    const prev = revDataRef.current[id] || {};
    revGuardar({ ...revDataRef.current, [id]: { ...prev, v, y: REVISION_ORDEN[revIdx][2], t: Date.now() } });
    revIr(revSiguientePendiente(revIdx), revAislar);
  }, [revIdx, revAislar, revGuardar, revIr, revSiguientePendiente]);
  const revFicha = useCallback(() => {
    const civ = CIVILIZATIONS.find(c => c.id === REVISION_ORDEN[revIdx][0]);
    if (civ) openProcessCard('civilizations', civ);
  }, [revIdx, openProcessCard]);

  // ── Globe messages ────────────────────────────────────────────────────────
  const onGlobeMsg = useCallback((e) => {
    try {
      const msg = JSON.parse(e.nativeEvent.data);
      // El motor vacio su cache de mallas (demasiados territorios acumulados):
      // se olvida lo enviado y se reenvia todo para que no falte ninguno.
      if (msg.type === 'cacheVaciada') {
        enviadasRef.current = new Set();
        forzarRepintado();
        return;
      }
      // Desalojo parcial: solo se olvidan esas claves; la proxima vez que
      // aparezcan volveran a viajar con sus coordenadas.
      if (msg.type === 'cacheOlvidado') {
        for (const k of (msg.claves || [])) enviadasRef.current.delete(k);
        return;
      }
      if (msg.type === 'revData') {
        let d = {}; try { d = msg.data ? JSON.parse(msg.data) : {}; } catch (_) { d = {}; }
        if (d && typeof d === 'object') { revDataRef.current = d; setRevData(d); }
        return;
      }
      if (msg.type === 'pinTap') {
        const ev = EVENTS.find(ev => ev.id === msg.id);
        if (ev) openEvent(ev);
      } else if (msg.type === 'routeTap') {
        const route = TRADE_ROUTES.find(r => r.id === msg.id);
        if (route) {
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setRouteCard(route);
        }
      } else if (msg.type === 'riverTap') {
        const river = RIVERS_INFO.find(r => r.id === msg.id);
        if (river) {
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setRiverCard(river);
        }
      } else if (msg.type === 'wonderTap') {
        const wonder = WONDERS.find(w => w.id === msg.id);
        if (wonder) {
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setWonderCard(wonder);
        }
      } else if (msg.type === 'migrationTap') {
        const mig = MIGRATIONS.find(m => m.id === msg.id);
        if (mig) {
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setMigrationCard(mig);
        }
      } else if (msg.type === 'languageTap') {
        const lang = LANGUAGES.find(l => l.id === msg.id);
        if (lang) {
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setLanguageCard(lang);
        }
      } else if (msg.type === 'religionTap') {
        const rel = RELIGIONS.find(r => r.id === msg.id);
        if (rel) {
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setReligionCard(rel);
        }
      } else if (msg.type === 'civilizationTap') {
        const civ = CIVILIZATIONS.find(c => c.id === msg.id);
        if (civ) {
          const yr = Math.round(yearRef.current);
          const period = periodoEn(civ.periods, yr);
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setCivilizationCard({ ...civ, periodStart: period?.start, periodEnd: period?.end, periodWikiTitle: period?.wikiTitle, periodName: period?.name });
        }
      } else if (msg.type === 'warTap') {
        const war = WARS.find(w => w.id === msg.id);
        if (war) {
          wasPlayingRef.current = isPlaying;
          setIsPlaying(false);
          globeRef.current?.postMessage(JSON.stringify({ type:'lockRotation' }));
          setWarCard({ ...war, focusBattleIdx: (msg.battleIdx != null ? msg.battleIdx : null) });
        }
      } else if (msg.type === 'zoomOutExit') {
        // Return to orbital
        globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
        if (wasPlayingRef.current) setIsPlaying(false);
        switchToOrbital(Math.round(yearRef.current));
      }
    } catch (_) {}
  }, [openEvent, isPlaying, switchToOrbital]);

  // ── Settings/Info modals ───────────────────────────────────────────────────
  const [showSettings, setShowSettings] = useState(false);
  const [showInfo,     setShowInfo]     = useState(false);

  return (
    <View style={[appSt.root, { backgroundColor: bgColor }]}>
      {/* High contrast overlay — darkens everything slightly when enabled */}
      {contrast && (
        <View pointerEvents="none" style={{
          ...StyleSheet.absoluteFillObject, zIndex:999,
          backgroundColor:'rgba(0,0,0,0.18)',
        }} />
      )}
      <StatusBar barStyle="light-content" hidden />

      {/* ── ORBITAL WebView ──────────────────────────────────────────────── */}
      <Animated.View style={[StyleSheet.absoluteFill, { opacity: orbitalOpacity }]}
        pointerEvents={screen === 'orbital' ? 'auto' : 'none'}>
        <WebView
          ref={orbitalRef}
          source={{ html: makeOrbitalHTML(SW, SH) }}
          style={StyleSheet.absoluteFill}
          originWhitelist={['*']} scrollEnabled={false} bounces={false}
          overScrollMode="never" backgroundColor="#04040d"
          javaScriptEnabled domStorageEnabled mixedContentMode="always"
          onMessage={onOrbitalMsg}
          onLoad={onOrbitalLoad}
        />
        {/* Orbital UI */}
        <TouchableOpacity style={[appSt.cornerBtn, appSt.topLeft]}
          onPress={() => setShowInfo(true)} activeOpacity={0.7}>
          <Info size={20} color={ICON_DIM} weight="regular" />
        </TouchableOpacity>
        <TouchableOpacity style={[appSt.cornerBtn, appSt.topRight]}
          onPress={() => setShowSettings(true)} activeOpacity={0.7}>
          <Gear size={20} color={ICON_DIM} weight="regular" />
        </TouchableOpacity>
        {showYearEditor && (
          <YearEditorModal currentYear={editorYear}
            onConfirm={handleYearEditorConfirm}
            onClose={() => setShowYearEditor(false)} />
        )}
        {showSettings && <SettingsModal onClose={() => setShowSettings(false)} onRevision={revEntrar} />}
        {showInfo     && <InfoModal     onClose={() => setShowInfo(false)} />}
      </Animated.View>

      {/* ── GLOBE WebView — always mounted, hidden when not active ───────── */}
      <Animated.View style={[StyleSheet.absoluteFill, { opacity: globeOpacity }]}
        pointerEvents={screen === 'globe' ? 'auto' : 'none'}>
        <WebView
          ref={globeRef}
          source={{ html: makeGlobeHTML(SW, SH) }}
          style={StyleSheet.absoluteFill}
          originWhitelist={['*']} scrollEnabled={false} bounces={false}
          overScrollMode="never" backgroundColor="#04040d"
          javaScriptEnabled domStorageEnabled mixedContentMode="always"
          onLoad={onWebViewLoad}
          onMessage={onGlobeMsg}
        />

        {/* Active process strip -- funciona como leyenda de colores (qué
            civ/ruta/guerra/etc. es cada color activo ahora mismo) y además
            se puede tocar para abrir la ficha directo. Antes tenía
            pointerEvents="none" en el contenedor entero, lo que -- sin
            querer -- también bloqueaba el gesto de scroll del ScrollView de
            adentro: con más chips de los que entran en una pantalla, no
            había forma de deslizar para ver/tocar el resto ("no se pueden
            mover"). "box-none" deja que el View en sí sea transparente al
            tap (no bloquea el globo detrás en las zonas vacías) pero permite
            que el ScrollView y los chips reciban sus propios gestos. */}
        {activeItems.length > 0 && (
          <ProcessStrip items={activeItems} onOpen={openProcessCard} />
        )}

        {/* Narrative */}
        {(processLayers.civilizations || processLayers.routes || processLayers.wars ||
          processLayers.migration || processLayers.religion || processLayers.languages) && !!narrative && (
          <View style={styles.narrative} pointerEvents="none">
            <Text style={styles.narrativeTxt}>{narrative}</Text>
          </View>
        )}

        {/* Top bar */}
        <View style={styles.topBar} pointerEvents="box-none">
          <TouchableOpacity style={styles.iconBtn} onPress={() => setShowSearch(true)} pointerEvents="auto">
            <MagnifyingGlass size={17} color="rgba(255,255,255,0.75)" weight="bold" />
          </TouchableOpacity>
          <YearWheel year={year} isPlaying={isPlaying}
            onYearChange={(y) => {
              yearRef.current = y; setYear(y); setStoreYear(y);
              sendPins(y, activeCatRef.current, toleranceRef.current, false);
              sendProcesses(y, processLayersRef.current, processItemsOnRef.current, false);
            }}
          />
          <TouchableOpacity
            style={[styles.iconBtn, showDrawer && styles.iconBtnActive]}
            onPress={() => setShowDrawer(true)} pointerEvents="auto">
            <List size={20} color={showDrawer ? '#378ADD' : 'rgba(255,255,255,0.75)'} weight="regular" />
          </TouchableOpacity>
        </View>

        {/* Play bar */}
        {!revOn && <PlayBar isPlaying={isPlaying} speed={speed} dir={playDir}
          onToggle={() => { forzarRepintado(); setIsPlaying(p => !p); }}
          onDirChange={(d) => { playDirRef.current = d; setPlayDir(d); forzarRepintado(); }}
          onSpeedChange={setSpeed}
          onReset={() => globeRef.current?.postMessage(JSON.stringify({ type:'resetGlobe' }))} />}
        {revOn && (
          <RevisionBar idx={revIdx} data={revData} aislar={revAislar}
            onPrev={() => revIr(revIdx - 1, revAislar)}
            onNext={() => revIr(revIdx + 1, revAislar)}
            onVeredicto={revVeredicto}
            onNota={() => setRevNotaDe(REVISION_ORDEN[revIdx][0])}
            onAislar={() => { const a = !revAislar; setRevAislar(a); revIr(revIdx, a); }}
            onLista={() => setShowRevLista(true)}
            onFicha={revFicha}
            onSalir={revSalir} />
        )}
        {showRevLista && <RevisionLista data={revData} idx={revIdx} onIr={(i) => revIr(i, revAislar)} onClose={() => setShowRevLista(false)} />}
        {revNotaDe && (
          <RevisionNota nombre={(CIVILIZATIONS.find(c => c.id === revNotaDe) || {}).name || revNotaDe}
            inicial={(revData[revNotaDe] || {}).n}
            onGuardar={(n) => { const prev = revDataRef.current[revNotaDe] || {}; revGuardar({ ...revDataRef.current, [revNotaDe]: { ...prev, n, t: Date.now() } }); setRevNotaDe(null); }}
            onClose={() => setRevNotaDe(null)} />
        )}

        {/* Search */}
        {showSearch && (
          <SearchModal onClose={() => setShowSearch(false)}
            onSelectEvent={(ev) => {
              setShowSearch(false);
              const evYear = ev.year;
              yearRef.current = evYear; setYear(evYear); setStoreYear(evYear);
              sendPins(evYear, activeCatRef.current, toleranceRef.current, true);
              sendProcesses(evYear, processLayersRef.current, processItemsOnRef.current, true);
              setTimeout(() => openEvent(ev), 120);
            }}
            onSelectProcess={(resultType, item) => {
              setShowSearch(false);
              const itemYear = firstYearOf(item);
              const jumpYear = itemYear != null ? itemYear : yearRef.current;
              yearRef.current = jumpYear; setYear(jumpYear); setStoreYear(jumpYear);
              // Enciende la capa completa y este ítem en particular -- si el
              // usuario la había apagado (o había apagado justo este ítem)
              // antes, el postMessage de abajo no dibujaría nada aunque el
              // año sea el correcto.
              const nextLayers = { ...processLayersRef.current, [resultType]: true };
              const nextItemsOn = {
                ...processItemsOnRef.current,
                [resultType]: { ...(processItemsOnRef.current[resultType] || {}), [item.id]: true },
              };
              setProcessLayers(nextLayers);
              setProcessItemsOn(nextItemsOn);
              sendPins(jumpYear, activeCatRef.current, toleranceRef.current, true);
              sendProcesses(jumpYear, nextLayers, nextItemsOn, true);
              setTimeout(() => openProcessCard(resultType, item), 120);
            }}
            onAskAI={(query) => {
              setShowSearch(false);
              askAIAbout(query || null);
            }}
          />
        )}
        {selectedEvent && <EventCard event={selectedEvent} onClose={closeEvent} activeCategories={activeCategories} onAskAI={askAIAbout} />}
        {routeCard && (
          <RouteInfoCard route={routeCard} onClose={() => {
            setRouteCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} />
        )}
        {riverCard && (
          <RiverInfoCard river={riverCard} onClose={() => {
            setRiverCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} />
        )}
        {wonderCard && (
          <WonderInfoCard wonder={wonderCard} onClose={() => {
            setWonderCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} />
        )}
        {migrationCard && (
          <MigrationInfoCard migration={migrationCard} onClose={() => {
            setMigrationCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} />
        )}
        {languageCard && (
          <LanguageInfoCard language={languageCard} onClose={() => {
            setLanguageCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} />
        )}
        {religionCard && (
          <ReligionInfoCard religion={religionCard} onClose={() => {
            setReligionCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} />
        )}
        {civilizationCard && (
          <CivilizationInfoCard civilization={civilizationCard} onClose={() => {
            setCivilizationCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} />
        )}
        {warCard && (
          <WarInfoCard war={warCard} onClose={() => {
            setWarCard(null);
            globeRef.current?.postMessage(JSON.stringify({ type:'unlockRotation' }));
            if (wasPlayingRef.current) setIsPlaying(true);
          }} onAskAI={askAIAbout} onBattlePress={(b, idx) => {
            // Tap en una batalla de la ficha: salta la línea de tiempo a su
            // año, centra el globo en su ubicación y deja esa fila resaltada
            // (mismo índice original que usa el tap directo sobre el mapa).
            const y = b.year;
            yearRef.current = y; setYear(y); setStoreYear(y);
            sendPins(y, activeCatRef.current, toleranceRef.current, true);
            sendProcesses(y, processLayersRef.current, processItemsOnRef.current, true);
            globeRef.current?.postMessage(JSON.stringify({ type:'rotateTo', lat:b.lat, lon:b.lon }));
            setWarCard(wc => (wc ? { ...wc, focusBattleIdx: idx } : wc));
          }} />
        )}
        {showDrawer && (
          <UnifiedDrawer
            activeCategories={activeCategories} onCategoryToggle={toggleCategory} onToggleAllEvents={toggleAllEvents}
            processLayers={processLayers} processItemsOn={processItemsOn}
            onProcessToggle={toggleProcess} onProcessItemToggle={toggleProcessItem}
            tolerance={tolerance} onToleranceChange={setTolerance}
            activeCivils={activeCivils} activeRoutes={activeRoutes} activeWars={activeWars}
            divisionLayers={divisionLayers} onDivisionToggle={toggleDivision}
            autoRotate={autoRotate} onToggleAutoRotate={toggleAutoRotate}
            flatMap={flatMap} onToggleFlatMap={toggleFlatMap}
            showCivilNames={processLayers.showCivilNames} onToggleCivilNames={toggleCivilNames}
            showCultures={processLayers.showCultures} onToggleCultures={toggleCultures}
            anioActual={year}
            onClose={() => setShowDrawer(false)}
          />
        )}
        {showChat && (
          <AIChatPanel
            onClose={() => setShowChat(false)}
            onNavigate={navigateFromAI}
            onResolveNav={resolveNavTarget}
            seed={chatSeed}
            messages={chatMessages}
            setMessages={setChatMessages}
          />
        )}
      </Animated.View>
    </View>
  );
}

